/**
 * T12 — what kind of machine is this, and what has the player asked for.
 *
 * The original had one answer to every question in this file: a 128x128 handset with a
 * keypad, no pointer, no rotation and no second window. A browser has none of that
 * settled, so the four decisions the rest of T12 depends on — how the 128x128 area is
 * scaled, whether on-screen buttons appear, whether tilt steers, and how wide the camera
 * is — are collected here as one options record, resolved once at boot.
 *
 * Each option is a three-way: an explicit query-string value wins, `auto` asks the
 * device. Query strings rather than a settings screen because the original has no
 * settings screen and T12 is not the task that invents one — `?fit=integer&controls=on`
 * is enough to test a phone layout on a desktop and a desktop layout on a phone, which is
 * what the acceptance check needs.
 *
 *   ?fit=integer|contain|auto   scale mode (default auto: integer on desktop, contain on touch)
 *   ?controls=on|off|auto       the touch pad (default auto: on when the device reports touch)
 *   ?tilt=1                     tilt steering, off unless asked for
 *   ?wide[=N]                   widescreen: N extra tile columns each side (default 3, max 8)
 *
 * Parsing is a pure function over the search string so the whole table is testable in
 * node; only `detectTouch()` touches a global, and it takes its inputs as arguments.
 */

/** How the 128x128 area is mapped onto the window. */
export type FitMode =
  /** Whole-device-pixel upscale, letterboxed. The parity path; see `Viewport`. */
  | 'integer'
  /** Largest scale that fits, fractional. Fills a phone screen at the cost of exactness. */
  | 'contain';

export type Preference<T> = T | 'auto';

/**
 * One tile is 12px (`TILE_SIZE` in `game/Level`, not imported: `core/` does not depend on
 * `game/`). Widescreen widens in whole tiles so the camera stays on the tile grid and
 * `TileMap`'s column walk needs no fractional first column.
 */
export const WIDE_TILE = 12;

/** `?wide` with no value. Three tiles a side is 200px total — 16:10-ish at 128 tall. */
export const WIDE_DEFAULT_TILES = 3;

/** Past this the level's own width (26 tiles at the narrowest) starts to run out. */
export const WIDE_MAX_TILES = 8;

export type PlatformOptions = {
  fit: Preference<FitMode>;
  /** `true` forces the touch pad on, `false` off, `auto` asks the device. */
  controls: Preference<boolean>;
  tilt: boolean;
  /** Extra tile columns drawn each side of the parity viewport. 0 is parity. */
  wideTiles: number;
};

export const DEFAULT_OPTIONS: PlatformOptions = {
  fit: 'auto',
  controls: 'auto',
  tilt: false,
  wideTiles: 0,
};

function clampInt(value: number, low: number, high: number): number {
  if (!Number.isFinite(value)) return low;
  return Math.min(high, Math.max(low, Math.trunc(value)));
}

/** Parse `location.search`. Unknown keys and unparseable values fall back to the default. */
export function parseOptions(search: string): PlatformOptions {
  const params = new URLSearchParams(search.startsWith('?') ? search.slice(1) : search);
  const options: PlatformOptions = { ...DEFAULT_OPTIONS };

  const fit = params.get('fit');
  if (fit === 'integer' || fit === 'contain' || fit === 'auto') options.fit = fit;

  const controls = params.get('controls');
  if (controls === 'on' || controls === '1') options.controls = true;
  else if (controls === 'off' || controls === '0') options.controls = false;
  else if (controls === 'auto') options.controls = 'auto';

  const tilt = params.get('tilt');
  options.tilt = tilt !== null && tilt !== '0' && tilt !== 'off';

  if (params.has('wide')) {
    const raw = params.get('wide');
    const tiles = raw === null || raw === '' || raw === '1' ? WIDE_DEFAULT_TILES : Number(raw);
    options.wideTiles = clampInt(tiles, 0, WIDE_MAX_TILES);
  }

  return options;
}

/** Enough of `navigator`/`window` to guess at a touchscreen, so a test can supply it. */
export type TouchProbe = {
  maxTouchPoints?: number;
  matchMedia?: (query: string) => { matches: boolean };
};

/**
 * Does this machine want thumb controls?
 *
 * `maxTouchPoints` alone says yes on a touch-capable laptop, where a keyboard is right
 * there and a pad over the screen is a nuisance; `(pointer: coarse)` alone says no on
 * some Android browsers. Both together is the usual compromise: a coarse *primary*
 * pointer plus at least one touch point.
 */
export function detectTouch(probe: TouchProbe): boolean {
  const points = probe.maxTouchPoints ?? 0;
  if (points <= 0) return false;
  const coarse = probe.matchMedia?.('(pointer: coarse)').matches;
  // No `matchMedia` at all (old WebView): trust the touch points.
  return coarse ?? true;
}

/** The options with every `auto` resolved against the device. */
export type ResolvedPlatform = {
  fit: FitMode;
  controls: boolean;
  tilt: boolean;
  wideTiles: number;
  /** Half the extra width, in virtual pixels: what the play area shifts right by. */
  wideMargin: number;
  /** Virtual width of the drawn area. 128 unless widescreen. */
  viewWidth: number;
  touch: boolean;
};

export function resolvePlatform(
  options: PlatformOptions,
  touch: boolean,
  baseWidth = 128,
): ResolvedPlatform {
  const wideMargin = options.wideTiles * WIDE_TILE;
  return {
    fit: options.fit === 'auto' ? (touch ? 'contain' : 'integer') : options.fit,
    controls: options.controls === 'auto' ? touch : options.controls,
    tilt: options.tilt,
    wideTiles: options.wideTiles,
    wideMargin,
    viewWidth: baseWidth + 2 * wideMargin,
    touch,
  };
}

/**
 * The `env(safe-area-inset-*)` values, in CSS pixels.
 *
 * There is no JS API for them, so this measures: a hidden element given the four insets
 * as padding, read back through `getComputedStyle`. Needs `viewport-fit=cover` in the
 * page's viewport meta or every value is 0 by definition. Returns zeros anywhere the
 * measurement is not available, which is every non-browser caller.
 */
export function readSafeAreaInsets(doc?: Document): {
  top: number;
  right: number;
  bottom: number;
  left: number;
} {
  const zero = { top: 0, right: 0, bottom: 0, left: 0 };
  const target = doc ?? (typeof document === 'undefined' ? null : document);
  if (!target?.body) return zero;

  const probe = target.createElement('div');
  probe.style.cssText = [
    'position:fixed',
    'visibility:hidden',
    'pointer-events:none',
    'top:0;left:0;width:0;height:0',
    'padding-top:env(safe-area-inset-top)',
    'padding-right:env(safe-area-inset-right)',
    'padding-bottom:env(safe-area-inset-bottom)',
    'padding-left:env(safe-area-inset-left)',
  ].join(';');
  target.body.appendChild(probe);
  try {
    const style = getComputedStyle(probe);
    return {
      top: parseFloat(style.paddingTop) || 0,
      right: parseFloat(style.paddingRight) || 0,
      bottom: parseFloat(style.paddingBottom) || 0,
      left: parseFloat(style.paddingLeft) || 0,
    };
  } catch {
    return zero;
  } finally {
    probe.remove();
  }
}
