import { MenuState } from './MenuState';
import { GameState } from './StateMachine';
import { FormBody, buildChrome, type Chrome } from './ui';

export class GameOverState extends GameState {
  readonly name = 'game-over';

  private chrome!: Chrome;

  private body!: FormBody;

  override async enter(): Promise<void> {
    const { i18n, session } = this.ctx;

    this.chrome = buildChrome(this.view);
    // `new Form(c.a(11))` on both paths.
    this.chrome.setTitle(i18n.t('GAME_OVER'));
    this.chrome.setSoftKeys(i18n.t('OK'), undefined);

    const paragraphs = [i18n.t(session.finished ? 'CONGRATS' : 'GAME_OVER')];
    if (session.newBestScore) paragraphs.push(i18n.t('NEW_HIGH_SCORE'));
    paragraphs.push(String(session.finalScore));

    this.body = new FormBody(this.chrome);
    this.body.setParagraphs(paragraphs);
  }

  override tick(): void {
    for (const edge of this.ctx.input.poll()) {
      if (edge.type !== 'down') continue;
      if (edge.action === 'SELECT' || edge.action === 'BACK' || edge.action === 'UP') {
        void this.ctx.machine.replace(MenuState);
        return;
      }
    }
  }
}
