/**
 * T6/T12 — bootstrap, standing in for `Bounce.startApp()` plus `a`'s constructor.
 *
 * The MIDlet's startup is: `Bounce.startApp()` makes an `a`; `a`'s constructor reads the
 * record store (`h()`), builds the `d` canvas, sets it current, and prepares the menu
 * strings (`e()`); `b.d()` starts the 40 ms timer. This does the same in the same order —
 * storage first, so the menu knows whether to offer `CONTINUE`; then the screen; then the
 * clock.
 *
 * Rendering is decoupled from simulation: Pixi's ticker drives `Loop.advance()`, which
 * runs whole 40 ms steps, and `render()` afterwards. The original had one rate for both;
 * splitting them is what lets the port draw at 60 Hz (or 120) without touching physics.
 *
 * T12 adds the four things a handset did not need and a browser does: the platform
 * options that decide how the 128x128 area is scaled and whether thumb controls appear
 * (`core/Platform`, `core/Viewport`, `core/TouchPad`), a preloader behind the splash
 * (`core/Assets`), and a lifecycle that stops the clock when the page loses the screen
 * (`core/Lifecycle`). Ordering still matters: options and storage before anything reads
 * them, the boot bundle before the first frame, the clock last.
 */
import { Application } from 'pixi.js';

import { initAssets } from './core/Assets';
import { AudioPlayer } from './core/Audio';
import { I18n } from './core/I18n';
import { Input } from './core/Input';
import { Lifecycle } from './core/Lifecycle';
import { Loop } from './core/Loop';
import { detectTouch, parseOptions, readSafeAreaInsets, resolvePlatform } from './core/Platform';
import { Storage } from './core/Storage';
import { Tilt } from './core/Tilt';
import { TouchPad } from './core/TouchPad';
import { VIEW_WIDTH, Viewport } from './core/Viewport';
import { Session } from './game/Session';
import { SplashState } from './states/SplashState';
import { StateMachine } from './states/StateMachine';

async function bootstrap(): Promise<void> {
  const canvas = document.getElementById('game-canvas') as HTMLCanvasElement;

  // `?fit=`, `?controls=`, `?tilt`, `?wide` — see `core/Platform`.
  const platform = resolvePlatform(
    parseOptions(window.location.search),
    detectTouch(navigator),
    VIEW_WIDTH,
  );

  const app = new Application();
  await app.init({
    canvas,
    resizeTo: window,
    // The letterbox around the play area. `d.paint()` clears to black too.
    background: 0x000000,
    // Pixel art: no smoothing anywhere, and full device resolution so `Viewport` can
    // pick an upscale that lands on whole device pixels.
    antialias: false,
    autoDensity: true,
    resolution: window.devicePixelRatio || 1,
    roundPixels: true,
  });

  // `a.h()` — read the store before anything asks what is in it.
  const storage = new Storage();

  const pad = new TouchPad();

  const viewport = new Viewport(app, {
    fit: platform.fit,
    controls: platform.controls,
    viewWidth: platform.viewWidth,
    // Re-measured per layout: a phone rotating changes which edge the notch is on.
    insets: () => readSafeAreaInsets(),
    onLayout: (metrics) => pad.setLayout(metrics.pad),
  });
  // The pad is drawn in the canvas's CSS pixels, not the game's, so it hangs off the
  // stage rather than off `viewport.root` — see `core/TouchPad`.
  app.stage.addChild(pad.view);
  pad.setLayout(viewport.current.pad);

  const input = new Input();
  input.attach();
  input.attachPointer(canvas, viewport, (x, y) => pad.actionAt(x, y));
  input.setHeldListener((action, held) => pad.setHeld(action, held));

  const audio = new AudioPlayer();
  // Browsers block autoplay; `Sound` did not. The context opens on the first gesture and
  // `play()` is a no-op until then, so nothing waits on this. The tones themselves are
  // fetched by the splash's preloader.
  audio.installUnlockListeners();

  // Tilt needs the same first gesture (iOS gates `deviceorientation` behind a permission
  // prompt that only a gesture may raise), and is off unless `?tilt` asked for it.
  const tilt = new Tilt(input);
  if (platform.tilt) {
    const start = (): void => {
      window.removeEventListener('pointerdown', start);
      void tilt.enable();
    };
    window.addEventListener('pointerdown', start, { passive: true });
  }

  await initAssets();

  // `a.e()` — the menu strings, and everything else the UI shows.
  const i18n = await I18n.load();

  // The rest of class `a`: the level, score, lives and high-score bookkeeping every
  // screen shares. T10 introduced it; see `src/game/Session.ts`.
  const session = new Session(storage);

  const machine = new StateMachine({
    viewport,
    platform,
    input,
    audio,
    i18n,
    storage,
    session,
  });
  await machine.replace(SplashState);

  // `f`'s `Timer.schedule(this, 0, 40)`.
  const loop = new Loop((tick) => machine.tick(tick));

  /**
   * `d.hideNotify()` and its absence. `Bounce.destroyApp` is the original's only call of
   * `a.a(3)`; a tab gets `pagehide` instead, and `visibilitychange` for the phone case
   * where `pagehide` never fires. See `core/Lifecycle` for why blur and hidden differ.
   */
  const lifecycle = new Lifecycle({
    onPersist: () => session.save(),
    onSuspend: (reason) => {
      input.clear();
      tilt.releaseHeld();
      pad.clearHeld();
      void audio.suspend();
      machine.suspend(reason);
    },
    onResume: () => {
      // Whatever time passed while away is not simulation time.
      loop.reset();
      void audio.resume();
      machine.resume();
    },
  });
  lifecycle.attach();

  app.ticker.add((ticker) => {
    // A hidden tab stops getting frames anyway; a blurred one does not, and running the
    // game behind another window is exactly what `hideNotify` was for.
    if (lifecycle.suspended) return;
    loop.advance(ticker.deltaMS);
    machine.render(loop.alpha);
  });

  if (import.meta.env.DEV) {
    // Handy for poking at the running game from the devtools console.
    Object.assign(window, {
      __PIXI_APP__: app,
      bounce: {
        app,
        loop,
        machine,
        viewport,
        input,
        audio,
        i18n,
        storage,
        session,
        platform,
        pad,
        tilt,
        lifecycle,
      },
    });
  }
}

void bootstrap();
