/**
 * T12 — pausing, and what the original did instead.
 *
 * The handset's hook is `Canvas.hideNotify()`, and `d`'s override is three lines:
 *
 *   public void hideNotify() {
 *     if (this.M) { if (this.aA != null) this.aA.a(); this.X.f(); }
 *     this.M = true;
 *   }
 *
 * `d.M` is "the canvas owns the display": it is set `false` immediately before every
 * `X.f()` / `X.d()` that hands the screen to a `List` or a `Form`, and back to `true`
 * here. So the guard distinguishes *the game navigated away* (M already false — do
 * nothing) from *the system took the screen away* (M still true — an incoming call, the
 * backlight, an app switch), and the response to the second is `aA.a()`, which is
 * `y &= 0xFFFFFFF0`, all four direction bits cleared, followed by `X.f()`: **the menu**.
 *
 * **Bounce has no pause screen.** Interrupt it and you are on the menu, with the level
 * still alive behind it — `d` is not destroyed, so `CONTINUE` resumes the same `d`. That
 * is the same path the soft keys take, and `PlayState` already reproduces it for the soft
 * keys by parking its `Playfield` on the session. T12 wires the browser's interruptions to
 * the same place.
 *
 * Two browser events, two different meanings, and they are not the same interruption:
 *
 * - **`visibilitychange` to hidden** — a tab switch, a minimise, a phone locking. The
 *   screen is gone. This is `hideNotify` and gets `hideNotify`'s behaviour.
 * - **`blur`** — another window took focus while this one is still on screen. The handset
 *   had no equivalent (nothing overlapped a `FullCanvas` without hiding it), and dropping
 *   the player to the menu because they clicked their editor would be a deviation nobody
 *   asked for. So blur freezes the clock and releases held keys, and leaves the screen
 *   alone.
 *
 * Both stop the simulation, and stopping it matters even for the hidden case: a hidden
 * tab's `requestAnimationFrame` stops on its own, but `Loop`'s accumulator would bank the
 * whole absence and spend it on the next frame, up to its five-tick clamp. Freezing and
 * `reset()`ing on resume is what makes the clamp never fire in the ordinary case.
 */

export type SuspendReason = 'hidden' | 'blur';

export type LifecycleOptions = {
  /** Raised on the transition into suspension, with what caused it. */
  onSuspend?: (reason: SuspendReason) => void;
  /** Raised on the transition back out, once both conditions clear. */
  onResume?: () => void;
  /** Last chance to write the record store: `pagehide`, and hidden on mobile. */
  onPersist?: () => void;
};

/** Enough of `document`/`window` for the class to be driven by a test. */
export type LifecycleTargets = {
  doc: Pick<Document, 'addEventListener' | 'removeEventListener'> & {
    visibilityState?: DocumentVisibilityState;
  };
  win: Pick<Window, 'addEventListener' | 'removeEventListener'>;
};

export class Lifecycle {
  private readonly options: LifecycleOptions;

  private targets: LifecycleTargets | null = null;

  private hidden = false;

  private blurred = false;

  constructor(options: LifecycleOptions = {}) {
    this.options = options;
  }

  /** True while the simulation should not run. */
  get suspended(): boolean {
    return this.hidden || this.blurred;
  }

  /** Why, for a caller that wants to say so. `hidden` wins when both are true. */
  get reason(): SuspendReason | null {
    if (this.hidden) return 'hidden';
    if (this.blurred) return 'blur';
    return null;
  }

  attach(targets: LifecycleTargets = { doc: document, win: window }): void {
    if (this.targets) return;
    this.targets = targets;
    // Seed from the current state: a tab restored into the background starts suspended.
    this.hidden = targets.doc.visibilityState === 'hidden';
    targets.doc.addEventListener('visibilitychange', this.onVisibility);
    targets.win.addEventListener('blur', this.onBlur);
    targets.win.addEventListener('focus', this.onFocus);
    targets.win.addEventListener('pagehide', this.onPageHide);
  }

  detach(): void {
    const targets = this.targets;
    if (!targets) return;
    targets.doc.removeEventListener('visibilitychange', this.onVisibility);
    targets.win.removeEventListener('blur', this.onBlur);
    targets.win.removeEventListener('focus', this.onFocus);
    targets.win.removeEventListener('pagehide', this.onPageHide);
    this.targets = null;
  }

  /** Drive the state machine directly. Exposed for the suite and for manual pausing. */
  set(flag: 'hidden' | 'blurred', value: boolean): void {
    const was = this.suspended;
    if (flag === 'hidden') this.hidden = value;
    else this.blurred = value;
    const now = this.suspended;
    if (now === was) return;
    if (now) this.options.onSuspend?.(this.reason ?? 'blur');
    else this.options.onResume?.();
  }

  private readonly onVisibility = (): void => {
    const hidden = this.targets?.doc.visibilityState === 'hidden';
    // A phone may never fire `pagehide`; hiding is the last moment we are sure of.
    if (hidden) this.options.onPersist?.();
    this.set('hidden', hidden);
  };

  private readonly onBlur = (): void => {
    this.set('blurred', true);
  };

  private readonly onFocus = (): void => {
    this.set('blurred', false);
  };

  private readonly onPageHide = (): void => {
    this.options.onPersist?.();
    this.set('hidden', true);
  };
}
