/**
 * T6 — persistence, replacing `javax.microedition.rms.RecordStore`.
 *
 * `a.h()` ("Read RMS") and `a.a(int)` ("Write RMS") are the whole of the original's save
 * system. They open one store, `"bounceRMS"`, and keep exactly **three records**, created
 * empty on first run when `getNumRecords() != 3`:
 *
 * | record | bytes | contents |
 * | --- | --- | --- |
 * | 1 | 1   | `a.f` — highest level reached, `min(level, 11)` |
 * | 2 | 4   | `a.h` — the high score |
 * | 3 | 255 | the resume snapshot, below |
 *
 * Record 3 is written by `a.a(3)` as: `long` timestamp, then a kind byte (`1` when
 * `a.M == 1`, i.e. saved mid-level; `2` when `a.M == 5`, saved on the level-complete
 * screen; `0` otherwise), then lives / hoops collected / level / ball size as bytes,
 * fourteen `int`s of score, camera and ball state, a table of the collectible cells still
 * standing, the moving platforms' offsets, and the trailer `0xDEADBEEF`. `a.h()` reads it
 * back and sets `a.L = 0` — "no save" — if the trailer is missing or anything throws.
 *
 * That trailer is the shape worth keeping: the original validates its own save and falls
 * back to "no save" rather than resuming into garbage. Here the equivalent is one
 * versioned JSON object under a single `localStorage` key, re-validated on read, with any
 * failure — a bumped version, a hand-edited value, a quota error, Safari private mode
 * throwing on `getItem` — degrading to defaults instead of propagating.
 *
 *   const storage = new Storage();
 *   storage.highScore;                  // 0 on a fresh browser
 *   storage.recordScore(4200);          // true when it beat the stored best
 *   storage.recordLevelReached(3);      // unlocks levels 1..3 in the New game list
 *
 * The snapshot's ball and world state stays out of the typed surface until T8 and T9 have
 * names for those fourteen `int`s; `SavedGame.extra` carries them in the meantime so that
 * T10 can start persisting a resumable game without this file having to guess.
 */

/** Levels shipped in the JAR; `a.a()` clamps the stored value with `Math.min(ak, 11)`. */
export const LEVEL_COUNT = 11;

/**
 * One key, one JSON object. Bump the suffix and every previous save is ignored rather
 * than mis-read — the coarse equivalent of `a.h()`'s `0xDEADBEEF` check.
 */
export const STORAGE_KEY = 'orange-ball.rms.v1';

const SCHEMA_VERSION = 1;

/** `a.L` / the kind byte in record 3: what a resume should do with the snapshot. */
export const SAVE_NONE = 0;
export const SAVE_IN_LEVEL = 1;
export const SAVE_LEVEL_START = 2;

export type SaveKind = typeof SAVE_NONE | typeof SAVE_IN_LEVEL | typeof SAVE_LEVEL_START;

/**
 * The resume snapshot. `kind` decides how `a.commandAction` restores it: `SAVE_IN_LEVEL`
 * re-enters the level at the saved ball position, `SAVE_LEVEL_START` restarts the saved
 * level with the saved score and lives.
 */
export type SavedGame = {
  kind: SaveKind;
  /** `System.currentTimeMillis()` at save time, kept for the same reason it was: none. */
  savedAtMs: number;
  /** 1-based level, `d.ak`. */
  level: number;
  /** `d.j`. */
  lives: number;
  /** `d.g`. */
  score: number;
  /** `d.aa` — hoops taken so far, against the header's hoop count. */
  hoopsCollected: number;
  /** `e.a` — 12 (deflated) or 16 (normal). */
  ballSize: number;
  /**
   * The rest of record 3 — camera, ball physics, surviving collectibles, platform
   * offsets. Left untyped until T8/T9 name `e`'s fields; see the file comment.
   */
  extra?: Readonly<Record<string, number>>;
};

export type SaveData = {
  version: number;
  /** `a.f`. Zero until a level is finished, which is why `a.g()` tests `f > 1`. */
  highestLevel: number;
  /** `a.h`. */
  highScore: number;
  savedGame: SavedGame | null;
};

/** The slice of the Web Storage API used here, so tests can pass a plain object. */
export type StorageLike = {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
};

const DEFAULTS: SaveData = {
  version: SCHEMA_VERSION,
  highestLevel: 0,
  highScore: 0,
  savedGame: null,
};

/**
 * `localStorage` when there is one and it is usable. Accessing the property throws in
 * some embedded and privacy-locked contexts, so the probe is a real read/write.
 */
function defaultBacking(): StorageLike | null {
  try {
    if (typeof localStorage === 'undefined') return null;
    const probe = `${STORAGE_KEY}.probe`;
    localStorage.setItem(probe, '1');
    localStorage.removeItem(probe);
    return localStorage;
  } catch {
    return null;
  }
}

function clampInt(value: unknown, min: number, max: number, fallback: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;
  return Math.min(max, Math.max(min, Math.trunc(value)));
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function parseExtra(value: unknown): Readonly<Record<string, number>> | undefined {
  if (!isRecord(value)) return undefined;
  const out: Record<string, number> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === 'number' && Number.isFinite(entry)) out[key] = entry;
  }
  return Object.keys(out).length > 0 ? out : undefined;
}

/**
 * Re-validate a snapshot on the way in. A save whose kind is `SAVE_NONE`, or whose level
 * is out of range, is discarded — `a.h()`'s `this.L = 0` by another name.
 */
function parseSavedGame(value: unknown): SavedGame | null {
  if (!isRecord(value)) return null;
  const kind = clampInt(value['kind'], SAVE_NONE, SAVE_LEVEL_START, SAVE_NONE) as SaveKind;
  if (kind === SAVE_NONE) return null;
  // Clamping the level would silently promote a hand-edited save to level 11. Reject it:
  // `a.h()` does the same with `this.L = 0` whenever record 3 fails to add up.
  const level = value['level'];
  if (typeof level !== 'number' || !Number.isInteger(level) || level < 1 || level > LEVEL_COUNT) {
    return null;
  }
  const extra = parseExtra(value['extra']);
  const game: SavedGame = {
    kind,
    savedAtMs: clampInt(value['savedAtMs'], 0, Number.MAX_SAFE_INTEGER, 0),
    level,
    lives: clampInt(value['lives'], 0, 99, 0),
    score: clampInt(value['score'], 0, Number.MAX_SAFE_INTEGER, 0),
    hoopsCollected: clampInt(value['hoopsCollected'], 0, 255, 0),
    ballSize: value['ballSize'] === 16 ? 16 : 12,
  };
  return extra ? { ...game, extra } : game;
}

function parse(raw: string | null): SaveData {
  if (!raw) return { ...DEFAULTS };
  try {
    const value: unknown = JSON.parse(raw);
    if (!isRecord(value) || value['version'] !== SCHEMA_VERSION) return { ...DEFAULTS };
    return {
      version: SCHEMA_VERSION,
      highestLevel: clampInt(value['highestLevel'], 0, LEVEL_COUNT, 0),
      highScore: clampInt(value['highScore'], 0, Number.MAX_SAFE_INTEGER, 0),
      savedGame: parseSavedGame(value['savedGame']),
    };
  } catch {
    return { ...DEFAULTS };
  }
}

export class Storage {
  private readonly backing: StorageLike | null;

  private data: SaveData;

  /**
   * `backing` defaults to `localStorage`. Pass `null` for a session that remembers
   * nothing — every getter still works, exactly as the MIDlet's empty `catch` left it.
   */
  constructor(backing: StorageLike | null = defaultBacking()) {
    this.backing = backing;
    this.data = this.read();
  }

  /** True when writes actually persist. False in private mode or with `null` backing. */
  get persistent(): boolean {
    return this.backing !== null;
  }

  /** `a.h` — the best score so far. */
  get highScore(): number {
    return this.data.highScore;
  }

  /** `a.f` — the highest level reached, so 0 before any level is completed. */
  get highestLevel(): number {
    return this.data.highestLevel;
  }

  /** The resume snapshot, or `null` when there is nothing to continue. */
  get savedGame(): SavedGame | null {
    return this.data.savedGame;
  }

  /** True when the menu should offer `CONTINUE` — `a.f()`'s `L == 1 || L == 2`. */
  get canContinue(): boolean {
    return this.data.savedGame !== null;
  }

  /**
   * Port of `a.a()`'s score half: store `score` when it beats the stored best and report
   * whether it did, which is the `mNewBestScore` flag the game-over form prints
   * `NEW_HIGH_SCORE` for.
   */
  recordScore(score: number): boolean {
    const value = clampInt(score, 0, Number.MAX_SAFE_INTEGER, 0);
    if (value <= this.data.highScore) return false;
    this.data = { ...this.data, highScore: value };
    this.write();
    return true;
  }

  /** Port of `a.a()`'s level half: `if (ak > f) f = min(ak, 11)`. */
  recordLevelReached(level: number): void {
    const value = clampInt(level, 0, LEVEL_COUNT, 0);
    if (value <= this.data.highestLevel) return;
    this.data = { ...this.data, highestLevel: value };
    this.write();
  }

  /** Port of `a.a(3)`. A `SAVE_NONE` kind clears the slot rather than storing a stub. */
  saveGame(game: SavedGame): void {
    const validated = parseSavedGame(game);
    this.data = { ...this.data, savedGame: validated };
    this.write();
  }

  /** Drop the resume slot, keeping the high score and the unlocked levels. */
  clearSavedGame(): void {
    if (!this.data.savedGame) return;
    this.data = { ...this.data, savedGame: null };
    this.write();
  }

  /** Forget everything. There is no equivalent in the original; debug and tests want it. */
  reset(): void {
    this.data = { ...DEFAULTS };
    try {
      this.backing?.removeItem(STORAGE_KEY);
    } catch {
      // Same treatment as every other failed write: the session keeps its own copy.
    }
  }

  /** A copy of the whole record, for a debug overlay or an export. */
  snapshot(): SaveData {
    return { ...this.data, savedGame: this.data.savedGame ? { ...this.data.savedGame } : null };
  }

  private read(): SaveData {
    try {
      return parse(this.backing?.getItem(STORAGE_KEY) ?? null);
    } catch {
      return { ...DEFAULTS };
    }
  }

  private write(): void {
    try {
      this.backing?.setItem(STORAGE_KEY, JSON.stringify(this.data));
    } catch {
      // Quota or a locked-down browser. The in-memory copy stands for this session, and
      // losing a high score beats throwing out of a level transition.
    }
  }
}
