/**
 * T12 — the asset manifest and the preloader.
 *
 * The MIDlet loads nothing up front. `Image.createImage("/icons/bouncesplash.png")` runs
 * in `d`'s constructor, `b.a(...)` reads a level out of the JAR when the level starts, and
 * `d.a(String)` builds a `Sound` from `sounds/*.ott` the first time it is played — all of
 * it off a local filesystem, all of it a few kilobytes, none of it worth a progress bar.
 *
 * Over HTTP the same lazy loading means the atlas arrives while the splash is already up,
 * and the first level's `fetch` sits between the menu and the game. So T12 does what the
 * original did not need to: names every file in one Pixi `Assets` manifest, and pulls the
 * lot down behind the splash.
 *
 * Three bundles, because they are wanted at three different moments:
 *
 * - **`boot`** is the splash image alone. `main.ts` awaits it, and that is the only wait
 *   before something is on screen.
 * - **`game`** is the atlas, which is every sprite in the game — tiles, ball, HUD.
 * - **`levels`** is all eleven level files, 3 KB each. Loading them together costs less
 *   than one round trip apiece and removes the fetch from the level transition.
 *
 * The tones are not in the manifest: they are decoded by `AudioPlayer` into note tables,
 * not textures, and Pixi's loader has nothing to add. `preloadTasks()` still counts them,
 * so the bar measures the whole wait rather than the part Pixi happens to own.
 *
 * The bar itself is `core/Preload`'s `Preloader`, a weighted fold over promises with no
 * Pixi in it, so `tests/platform.test.ts` can check the arithmetic without a renderer.
 */
import { Assets, type AssetsManifest } from 'pixi.js';

import type { AudioPlayer } from './Audio';
import type { PreloadTask } from './Preload';

export { Preloader, type PreloadTask, type ProgressReport } from './Preload';

/** How many level files ship. Mirrors `Storage.LEVEL_COUNT` and `levels/001..011`. */
export const LEVEL_COUNT = 11;

/** The splash bundle: everything needed before the first frame. */
export const BOOT_BUNDLE = 'boot';

/** The atlas. Wanted before the first level, loaded behind the splash. */
export const GAME_BUNDLE = 'game';

/** All eleven level files. */
export const LEVELS_BUNDLE = 'levels';

/** `assets/levels/NNN.json`, which is also its alias. */
export function levelAsset(id: number): string {
  return `levels/${String(id).padStart(3, '0')}.json`;
}

export const MANIFEST: AssetsManifest = {
  bundles: [
    {
      name: BOOT_BUNDLE,
      assets: [{ alias: 'images/splash.png', src: 'images/splash.png' }],
    },
    {
      name: GAME_BUNDLE,
      assets: [
        { alias: 'atlas.json', src: 'atlas.json' },
        { alias: 'images/icon.png', src: 'images/icon.png' },
      ],
    },
    {
      name: LEVELS_BUNDLE,
      assets: Array.from({ length: LEVEL_COUNT }, (_, index) => {
        const src = levelAsset(index + 1);
        return { alias: src, src };
      }),
    },
  ],
};

let initialised: Promise<void> | null = null;

/**
 * Register the manifest. Idempotent, and safe to call from more than one place —
 * `Assets.init` throws on a second call, which is exactly the kind of thing that only
 * shows up after a hot reload.
 */
export function initAssets(): Promise<void> {
  // No `basePath`: every src is relative and `vite.config.ts` sets `base: './'`, so the
  // build works from a subdirectory the same way `fetch('audio/pop.json')` already did.
  initialised ??= Assets.init({ manifest: MANIFEST });
  return initialised;
}

/**
 * Everything the splash waits on: the atlas, the eleven levels, the three tones.
 *
 * Weights are rough byte shares — the atlas is one PNG and by far the biggest thing here,
 * the levels are 33 KB of JSON between them, the tones a few hundred bytes each. Getting
 * these exactly right is not the point; a bar that spends 80% of its time in one bundle
 * without saying so is.
 */
export function preloadTasks(audio: AudioPlayer): PreloadTask[] {
  return [
    {
      name: GAME_BUNDLE,
      weight: 6,
      run: (report) => Assets.loadBundle(GAME_BUNDLE, report),
    },
    {
      name: LEVELS_BUNDLE,
      weight: 3,
      run: (report) => Assets.loadBundle(LEVELS_BUNDLE, report),
    },
    {
      name: 'audio',
      weight: 1,
      run: () => audio.load(),
    },
  ];
}
