/**
 * T12 — the on-screen controls.
 *
 * The handset had three keys that mattered: `4`/left, `6`/right and `2`/up, or the
 * D-pad's `LEFT`, `RIGHT` and `UP` game actions. `e.b()` reads exactly three bits (8, 2
 * and 1) and `DOWN` is set and cleared by `d.keyPressed` and never read, so a fourth
 * button would be a lie — see `Ball.pressKey`. Three buttons it is: two steering, one
 * bounce.
 *
 * PLAN.md §T12 asks for them **outside the 128x128 play area**, so they are drawn in the
 * band `Viewport` reserves rather than over the game, and they live in the canvas's
 * CSS-pixel space (a child of `app.stage`, not of the scaled `viewport.root`) — a button
 * scaled by the game's upscale would be 8 physical pixels wide on a phone at 1x and half
 * the screen on a desktop at 6x. Thumb targets are measured in millimetres of glass, not
 * in game pixels.
 *
 * The geometry is a pure function of the two regions so it is testable in node, and the
 * hit test is deliberately more generous than the drawing: `HIT_SLOP` widens each circle,
 * because a thumb that lands two pixels off the edge of a button meant to press it.
 *
 * Sliding counts. A pointer that goes down on LEFT and slides onto RIGHT releases the one
 * and presses the other, which is how a thumb actually plays a game like this; the
 * original's keypad could not do it, but the original's keypad also did not move.
 */
import { Container, Graphics } from 'pixi.js';

import type { Action } from './Input';
import { hitButton, padButtons, type PadButton, type PadRegions } from './Layout';

export { HIT_SLOP, hitButton, padButtons, type PadButton, type PadGlyph } from './Layout';

const IDLE_FILL = 0xffffff;
const IDLE_ALPHA = 0.1;
const HELD_ALPHA = 0.26;
const RING_ALPHA = 0.32;
const GLYPH_ALPHA = 0.75;

/**
 * Draws the pad and answers "which button is under this point".
 *
 * It owns no event listeners: `Input.attachPointer` does the pointer plumbing for the
 * keyboard and the pad alike, and takes this object's `actionAt` as its hit test. One
 * place decides that a press happened; this one decides where.
 */
export class TouchPad {
  readonly view = new Container();

  private readonly graphics = new Graphics();

  private buttons: readonly PadButton[] = [];

  private readonly held = new Set<Action>();

  constructor() {
    this.view.addChild(this.graphics);
    this.view.visible = false;
    // The pad is decoration plus a hit table; Pixi's own hit testing never sees it.
    this.view.eventMode = 'none';
    this.view.interactiveChildren = false;
  }

  destroy(): void {
    this.view.destroy({ children: true });
  }

  /** Re-place the buttons for a new layout. `null` hides the pad. */
  setLayout(pad: PadRegions | null): void {
    this.buttons = pad ? padButtons(pad) : [];
    this.view.visible = this.buttons.length > 0;
    this.draw();
  }

  /** Canvas-space hit test, for `Input`. */
  actionAt(x: number, y: number): Action | undefined {
    return hitButton(this.buttons, x, y)?.action;
  }

  /** Light a button up. `Input` reports every press, whatever its source. */
  setHeld(action: Action, held: boolean): void {
    const changed = held ? !this.held.has(action) : this.held.delete(action);
    if (held) this.held.add(action);
    if (changed) this.draw();
  }

  clearHeld(): void {
    if (this.held.size === 0) return;
    this.held.clear();
    this.draw();
  }

  private draw(): void {
    this.graphics.clear();
    for (const button of this.buttons) {
      const down = this.held.has(button.action);
      this.graphics
        .circle(button.cx, button.cy, button.r)
        .fill({ color: IDLE_FILL, alpha: down ? HELD_ALPHA : IDLE_ALPHA })
        .circle(button.cx, button.cy, button.r)
        .stroke({ color: IDLE_FILL, alpha: RING_ALPHA, width: 2 });
      this.drawGlyph(button);
    }
  }

  /** A filled triangle — the arrow keys the instructions screen talks about. */
  private drawGlyph(button: PadButton): void {
    const size = button.r * 0.42;
    const { cx, cy } = button;
    const points: number[] =
      button.glyph === 'left'
        ? [cx + size * 0.6, cy - size, cx + size * 0.6, cy + size, cx - size * 0.7, cy]
        : button.glyph === 'right'
          ? [cx - size * 0.6, cy - size, cx - size * 0.6, cy + size, cx + size * 0.7, cy]
          : [cx - size, cy + size * 0.6, cx + size, cy + size * 0.6, cx, cy - size * 0.7];
    this.graphics.poly(points).fill({ color: IDLE_FILL, alpha: GLYPH_ALPHA });
  }
}
