/**
 * T12 — a weighted progress fold, with no renderer and no network in it.
 *
 * The splash's bar measures three unrelated things — a Pixi bundle, another Pixi bundle,
 * and `AudioPlayer.load`'s three `fetch`es — so the fold is written against promises
 * rather than against `Assets`, and lives apart from `core/Assets` so the arithmetic is
 * testable in node. See `core/Assets.preloadTasks` for what the game actually loads.
 */

export type ProgressReport = (fraction: number) => void;

export type PreloadTask = {
  name: string;
  /** Relative share of the bar. Defaults to 1. */
  weight?: number;
  /** Runs the work, calling `report` with its own 0..1 progress where it can. */
  run: (report: ProgressReport) => Promise<unknown>;
};

/**
 * Runs tasks in parallel and folds their progress into one 0..1 fraction.
 *
 * A task that never reports still counts: it contributes 0 until it settles and its full
 * weight afterwards, so a bar made only of such tasks steps rather than slides — which is
 * honest, and better than a fake animation. **A failed task still completes the bar.** An
 * asset that 404s must not wedge the splash forever; the failure surfaces where the asset
 * is actually used, and `failures` records it for a caller that wants to say so.
 */
export class Preloader {
  private readonly tasks: readonly PreloadTask[];

  private readonly progress: number[];

  readonly failures: { name: string; error: unknown }[] = [];

  constructor(tasks: readonly PreloadTask[]) {
    this.tasks = tasks;
    this.progress = tasks.map(() => 0);
  }

  private get totalWeight(): number {
    return this.tasks.reduce((sum, task) => sum + (task.weight ?? 1), 0) || 1;
  }

  /** Weighted mean of every task's reported progress, clamped to 0..1. */
  fraction(): number {
    let done = 0;
    this.tasks.forEach((task, index) => {
      done += (this.progress[index] ?? 0) * (task.weight ?? 1);
    });
    return Math.min(1, Math.max(0, done / this.totalWeight));
  }

  async run(onProgress?: ProgressReport): Promise<void> {
    onProgress?.(this.tasks.length === 0 ? 1 : 0);

    await Promise.all(
      this.tasks.map(async (task, index) => {
        const report: ProgressReport = (value) => {
          const clamped = Math.min(1, Math.max(0, value));
          if (clamped <= (this.progress[index] ?? 0)) return; // never run backwards
          this.progress[index] = clamped;
          onProgress?.(this.fraction());
        };
        try {
          await task.run(report);
        } catch (error) {
          this.failures.push({ name: task.name, error });
        }
        this.progress[index] = 1;
        onProgress?.(this.fraction());
      }),
    );

    onProgress?.(1);
  }
}
