/**
 * T10 — the canvas, i.e. everything in class `d` that `Playfield` is not.
 *
 * T8 took `d.a()`'s gameplay tick — the band scroll, the ball step, the respawn, the
 * hazards, the door — into `src/game/Playfield.ts`, and said the rest was T10's. The rest
 * is this file, and it is four things:
 *
 * 1. **The drawing.** `d.n()` composes the frame: the tile buffer at `-I`, the ball
 *    (`aA.a(A)`), the deferred hoop fronts, then the HUD strip. Here that is `TileMap`'s
 *    two containers with the ball sprite between them, `Hud` on top, and a mask over the
 *    play area so nothing leaks into the strip.
 * 2. **The keys.** `d.keyPressed`/`keyReleased` map four game actions onto `e.c(int)` /
 *    `e.a(int)` bit sets. `Input` already resolves those actions, so this pushes the bits.
 * 3. **The lifecycle.** `d.a()`'s tail acts on `d.f` — bank 5000, step the level, and go
 *    to `X.d()` or, past level 011, `X.b(true)` — and its head acts on the game-over arm.
 *    `Playfield` raises both as flags; this turns them into screens.
 * 4. **The soft key.** `case -6/-7` sets `M = false` and calls `X.f()`: back to the menu,
 *    with the level left running behind it. That is what makes `CONTINUE` mean two
 *    different things in `a.commandAction`, and it is reproduced by keeping the field on
 *    the `Session` rather than tearing it down.
 *
 * ## The one deliberate deviation
 *
 * The original resumes a suspended level by keeping the whole `d` alive behind the menu.
 * A `StateMachine` state is destroyed on exit, so `PlayState` hands its `Playfield` to
 * the session's `suspended` slot on the way out and picks it back up if the next entry is
 * a `CONTINUE`. The simulation object is the same one; only its view is rebuilt.
 *
 * ## T12
 *
 * Two additions, and they pull in opposite directions.
 *
 * `suspend()` is `d.hideNotify()` — clear the direction bits, go to the menu, leave the
 * level running behind it — and it is the same path the soft keys already took, so losing
 * the screen to a phone call and pressing the soft key are once again the same event. See
 * `core/Lifecycle` for which browser events count as losing the screen.
 *
 * **Widescreen** (`?wide`) is the one thing in the port that is not parity by
 * construction. `platform.wideMargin` pixels are drawn either side of the 128px viewport
 * by handing `TileMap` a camera shifted left by that margin and a wider window; the camera
 * itself, the collision scan and every constant in `Physics` are untouched, so the
 * simulation stays bit-identical to the parity run and only the framing differs. It still
 * makes the game easier — a hazard you can see coming is a hazard you can plan for — which
 * is why it is behind a flag and off by default. `docs/PARITY.md` records it as such.
 */
import { Assets, Container, Graphics, Sprite, type Spritesheet } from 'pixi.js';

import { levelAsset } from '../core/Assets';
import type { SuspendReason } from '../core/Lifecycle';
import { PLAY_HEIGHT, VIEW_HEIGHT, VIEW_WIDTH } from '../core/Viewport';
import { DYING, type BallSound } from '../game/Ball';
import { HUD_TOP, Hud, meterTicks } from '../game/Hud';
import { TILE_SIZE, type LevelJson } from '../game/Level';
import { Level } from '../game/Level';
import { KEY_DOWN, KEY_LEFT, KEY_RIGHT, KEY_UP } from '../game/Physics';
import { Playfield } from '../game/Playfield';
import { TileMap } from '../game/TileMap';
import { HUD_COLOUR } from '../game/Tiles';
import { GameOverState } from './GameOverState';
import { LevelCompleteState } from './LevelCompleteState';
import { MenuState } from './MenuState';
import { GameState } from './StateMachine';

/** The atlas T2 wrote. Loaded once; `Assets` caches it for every later level. */
export const ATLAS = 'atlas.json';

/** `d`'s `getGameAction` cases, in the order `keyPressed` writes them. */
const ACTION_BITS = {
  LEFT: KEY_LEFT,
  RIGHT: KEY_RIGHT,
  UP: KEY_UP,
  DOWN: KEY_DOWN,
} as const;

/**
 * T12 — through `Assets` rather than `fetch`, so the copy the splash already pulled down
 * is the copy used here and a level change costs no round trip. `Assets` hands back the
 * same parsed object every time, hence the fresh `Level` around it: `Level` mutates its
 * tiles (a collected crystal writes its cell) and a second play must not inherit the
 * first one's collectibles.
 */
export async function loadLevel(id: number): Promise<Level> {
  return new Level(await Assets.load<LevelJson>(levelAsset(id)));
}

export class PlayState extends GameState {
  readonly name = 'play';

  private field!: Playfield;

  private map!: TileMap;

  private hud!: Hud;

  private ball!: Sprite;

  private sheet!: Spritesheet;

  /** Set once a transition has been requested, so a slow `enter()` cannot double-fire. */
  private leaving = false;

  override async enter(): Promise<void> {
    const { session, i18n, platform } = this.ctx;
    const margin = platform.wideMargin;
    const bandWidth = VIEW_WIDTH + 2 * margin;

    this.sheet = await Assets.load(ATLAS);
    this.sheet.textureSource.scaleMode = 'nearest';

    // `a.commandAction`'s `M == 1` arm: the level was left running behind the menu, so
    // pick it up rather than restarting it.
    const resumed = session.suspended;
    if (resumed !== null && resumed.level.id === session.level) {
      this.field = resumed;
    } else {
      this.field = new Playfield(await loadLevel(session.level), {
        lives: session.lives,
        score: session.score,
        onSound: (effect: BallSound) => this.ctx.audio.play(effect),
      });
    }
    session.suspended = null;

    this.map = new TileMap(this.field.level, this.sheet, {
      door: this.field.door,
      viewWidth: bandWidth,
    });
    this.ball = new Sprite();
    this.hud = new Hud(this.sheet);
    this.hud.bannerText = i18n.t('LEVEL', [String(this.field.level.id)]);

    // `d.n()`'s order: tiles, ball, the deferred hoop fronts. The mask is the 96px
    // play area, which the original gets for free from `b.H` being 96 tall.
    const play = new Container();
    play.addChild(this.map.view, this.ball, this.map.front);
    const mask = new Graphics().rect(0, 0, bandWidth, PLAY_HEIGHT).fill(0xffffff);
    play.addChild(mask);
    play.mask = mask;
    // This view sits inside `viewport.screen`, which widescreen insets by `margin`; the
    // band is the one thing that wants the whole of `viewport.root`, so it steps back out.
    play.x = -margin;

    // The row the original leaves as whatever the buffer held; black is the frame clear.
    const gutter = new Graphics().rect(-margin, 0, bandWidth, VIEW_HEIGHT).fill(0x000000);

    this.view.addChild(gutter, play);

    // Widescreen leaves the HUD its 128 centred pixels — every coordinate in `d.n()` is
    // hard-wired to that width — and runs the strip out to the edges behind it, so the
    // band does not end in two black rectangles.
    if (margin > 0) {
      this.view.addChild(
        new Graphics().rect(-margin, HUD_TOP, bandWidth, VIEW_HEIGHT - HUD_TOP).fill(HUD_COLOUR),
      );
    }

    this.view.addChild(this.hud.view);
    this.draw();
  }

  override exit(): void {
    // `d` survives `X.f()`; the `Playfield` has to survive this state for the same reason.
    if (!this.field.gameOver && !this.field.levelComplete) {
      this.ctx.session.suspended = this.field;
    }
    this.map.destroy();
  }

  override tick(): void {
    if (this.leaving) return;

    const { input, session } = this.ctx;

    // `case -6: case -7:` — the soft keys, before anything reaches the ball.
    for (const edge of input.poll()) {
      if (edge.type === 'down' && (edge.action === 'BACK' || edge.action === 'PAUSE')) {
        this.leaving = true;
        void this.ctx.machine.replace(MenuState);
        return;
      }
    }

    for (const [action, bit] of Object.entries(ACTION_BITS)) {
      if (input.isDown(action as keyof typeof ACTION_BITS)) this.field.ball.pressKey(bit);
      else this.field.ball.releaseKey(bit);
    }

    this.field.tick();

    // `d.a()` reads the two outcomes in this order and returns on the first.
    if (this.field.gameOver) {
      this.leaving = true;
      session.lives = this.field.lives;
      session.score = this.field.score;
      session.endGame(false);
      void this.ctx.machine.replace(GameOverState);
      return;
    }

    if (this.field.levelComplete) {
      this.leaving = true;
      session.lives = this.field.lives;
      session.score = this.field.score;
      const finished = session.completeLevel();
      void this.ctx.machine.replace(finished ? GameOverState : LevelCompleteState);
      return;
    }

    // Between levels the run's score and lives live on the session, so keep them level.
    session.score = this.field.score;
    session.lives = this.field.lives;
  }

  override render(): void {
    if (this.leaving) return;
    this.draw();
  }

  /**
   * `d.hideNotify()`. `aA.a()` clears the four direction bits — a key held when the screen
   * went away is not held when it comes back — and then, for a real loss of the screen,
   * `X.f()`: the menu, with the level parked on the session by `exit()`.
   */
  override suspend(reason: SuspendReason): void {
    if (this.leaving) return;
    this.field.ball.releaseDirections();
    if (reason !== 'hidden') return;
    this.leaving = true;
    void this.ctx.machine.replace(MenuState);
  }

  /** `d.n()` plus `d.paint()`, minus the dirty-flag bookkeeping a GPU makes pointless. */
  private draw(): void {
    const { camera, ball } = this.field;
    // Widescreen shifts the whole band left by the margin and lets the wider window fill
    // it; `camera.x` itself is the parity value and nothing reads this shifted one back.
    const camX = camera.x - this.ctx.platform.wideMargin;
    this.map.update(camX, camera.y);

    // `e.a(Graphics)`: the burst sprite is drawn from a fixed 6px offset while dying, the
    // ball from its own radius otherwise.
    const dying = ball.state === DYING;
    const frame = dying ? 'ball_burst' : ball.size === 16 ? 'ball_large' : 'ball_small';
    const texture = this.sheet.textures[frame];
    if (texture) this.ball.texture = texture;
    const offset = dying ? TILE_SIZE / 2 : ball.radius;
    this.ball.position.set(ball.x - offset - camX, ball.y - offset - camera.y);

    this.hud.update({
      score: this.field.score,
      lives: this.field.lives,
      hoopsLeft: this.field.level.hoopCount - this.field.hoopsTaken,
      boostTicks: meterTicks(ball.speedTicks, ball.gravityTicks, ball.jumpTicks),
      bannerTicks: this.field.bannerTicks,
    });
  }
}
