/**
 * T10 — the menu chrome, and the one place in the port that is a *reconstruction* rather
 * than a transcription.
 *
 * Everything else in `src/` can be traced to a line of bytecode. This cannot: `a.f()`
 * builds a `List(title, IMPLICIT)` and `a.b()`/`a.c()`/`a.d()` build `Form`s, and MIDP
 * hands both to the **handset's** UI toolkit. The JAR contains no chrome, no colours and
 * no font; what a Series 40 phone drew around those items in 2004 is a property of the
 * phone. So this file reproduces the *structure* MIDP guarantees — a title, a scrolling
 * body, a soft-key label at each bottom corner, one highlighted item in a list — in the
 * plainest form that fits 128x128, and says so rather than pretending to parity.
 *
 * Two structural facts are the original's and are not up for redesign:
 *
 * - **A `List` in `IMPLICIT` mode fires its selection on the item, not on a command.**
 *   `commandAction` receives `List.SELECT_COMMAND` and reads `getSelectedIndex()`. So
 *   `SELECT` acts on the highlighted row and there is no separate confirm step.
 * - **The commands are two at most**, and `a` only ever attaches `Back` (`c.a(7)`),
 *   `Exit` (`c.a(10)`), `OK` (`c.a(18)`) and `Continue` (`c.a(9)`). Their labels come
 *   from `I18n`, so they localize with everything else.
 *
 * T11 owns the pixel comparison against the recording; if the strip heights are wrong,
 * this is the file that changes and nothing else does.
 */
import { Container, Graphics } from 'pixi.js';

import { BitmapText, CELL_HEIGHT, LINE_HEIGHT, measureText, wrapText } from '../core/BitmapFont.ts';
import { VIEW_HEIGHT, VIEW_WIDTH } from '../core/Viewport.ts';

/** Body ground. MIDP forms are light; the game's own screens are the dark ones. */
export const PAGE_COLOUR = 0xf4f4f4;

export const BODY_TEXT_COLOUR = 0x101018;

/** Title strip, and the soft-key strip, share the game's HUD blue. */
export const BAR_COLOUR = 0x0853aa;

export const BAR_TEXT_COLOUR = 0xfffffe;

/** The highlight behind the selected row of a `List`. */
export const SELECTION_COLOUR = 0xff9613;

export const SELECTION_TEXT_COLOUR = 0x101018;

/** Title bar: one line of text plus a pixel of padding above and below. */
export const BAR_HEIGHT = CELL_HEIGHT + 3;

export const TITLE_TOP = 0;

export const SOFTKEY_TOP = VIEW_HEIGHT - BAR_HEIGHT;

/** The scrollable area between the two bars. */
export const BODY_TOP = BAR_HEIGHT + 1;

export const BODY_HEIGHT = SOFTKEY_TOP - 1 - BODY_TOP;

/** Left inset for body text and for the soft-key labels. */
export const MARGIN = 2;

export const BODY_WIDTH = VIEW_WIDTH - MARGIN * 2;

/** Rows of a list, and lines of a form, that fit in the body at once. */
export const VISIBLE_LINES = Math.floor((BODY_HEIGHT + (LINE_HEIGHT - CELL_HEIGHT)) / LINE_HEIGHT);

/** A 2px scroll rail down the right edge, shown only when the body overflows. */
export const SCROLLBAR_WIDTH = 2;

export type Chrome = {
  /** Add body content here; it is already clipped to the body area. */
  readonly body: Container;
  setTitle(text: string): void;
  /** The two soft keys. `undefined` hides one. */
  setSoftKeys(left: string | undefined, right: string | undefined): void;
  /** Draw the rail for a body `total` lines long scrolled to `first`. */
  setScroll(first: number, total: number): void;
};

/**
 * Build the standard screen: page fill, title bar, clipped body, soft-key bar.
 *
 * The body is masked rather than merely positioned, so a list that scrolls does not paint
 * its next row over the soft keys.
 */
export function buildChrome(view: Container): Chrome {
  view.addChild(new Graphics().rect(0, 0, VIEW_WIDTH, VIEW_HEIGHT).fill(PAGE_COLOUR));
  view.addChild(new Graphics().rect(0, TITLE_TOP, VIEW_WIDTH, BAR_HEIGHT).fill(BAR_COLOUR));
  view.addChild(
    new Graphics().rect(0, SOFTKEY_TOP, VIEW_WIDTH, VIEW_HEIGHT - SOFTKEY_TOP).fill(BAR_COLOUR),
  );

  const title = new BitmapText('', { colour: BAR_TEXT_COLOUR });
  title.position.set(MARGIN, TITLE_TOP + 2);
  view.addChild(title);

  const left = new BitmapText('', { colour: BAR_TEXT_COLOUR });
  left.position.set(MARGIN, SOFTKEY_TOP + 2);
  view.addChild(left);

  const right = new BitmapText('', { colour: BAR_TEXT_COLOUR, align: 1 });
  right.position.set(VIEW_WIDTH - MARGIN, SOFTKEY_TOP + 2);
  view.addChild(right);

  const body = new Container();
  body.position.set(0, BODY_TOP);
  const mask = new Graphics().rect(0, BODY_TOP, VIEW_WIDTH, BODY_HEIGHT).fill(0xffffff);
  view.addChild(body, mask);
  body.mask = mask;

  const rail = new Graphics();
  view.addChild(rail);

  return {
    body,
    setTitle(text) {
      // A title longer than the bar is cut, not wrapped: MIDP gives it one line.
      title.text = clip(text, VIEW_WIDTH - MARGIN * 2);
    },
    setSoftKeys(leftLabel, rightLabel) {
      left.text = leftLabel ?? '';
      right.text = rightLabel ?? '';
    },
    setScroll(first, total) {
      rail.clear();
      if (total <= VISIBLE_LINES) return;
      const x = VIEW_WIDTH - SCROLLBAR_WIDTH;
      rail.rect(x, BODY_TOP, SCROLLBAR_WIDTH, BODY_HEIGHT).fill(0xc0c8d0);
      const height = Math.max(4, Math.round((BODY_HEIGHT * VISIBLE_LINES) / total));
      const span = BODY_HEIGHT - height;
      const top = BODY_TOP + Math.round((span * first) / (total - VISIBLE_LINES));
      rail.rect(x, top, SCROLLBAR_WIDTH, height).fill(BAR_COLOUR);
    },
  };
}

/** Cut a string to whole glyphs that fit in `width`. */
export function clip(text: string, width: number): string {
  const chars = [...text];
  while (chars.length > 0 && measureText(chars.join('')) > width) chars.pop();
  return chars.join('');
}

/**
 * The rows of a `List`. Owns the selection, the highlight and the scroll offset; the
 * state above it owns what selecting a row means.
 */
export class ListBody {
  private readonly rows: BitmapText[] = [];

  private readonly highlight = new Graphics();

  private readonly layer = new Container();

  private items: readonly string[] = [];

  private first = 0;

  /** `List.getSelectedIndex()`. */
  selected = 0;

  constructor(private readonly chrome: Chrome) {
    chrome.body.addChild(this.highlight, this.layer);
  }

  get count(): number {
    return this.items.length;
  }

  /** `List.append` in bulk, then `setSelectedIndex`. */
  setItems(items: readonly string[], selected = 0): void {
    this.items = items;
    this.selected = items.length === 0 ? 0 : Math.min(Math.max(0, selected), items.length - 1);
    this.first = 0;
    this.refresh();
  }

  /** Move the highlight, wrapping — a MIDP `List` wraps at both ends. */
  move(delta: number): void {
    if (this.items.length === 0) return;
    this.selected = (this.selected + delta + this.items.length) % this.items.length;
    this.refresh();
  }

  private refresh(): void {
    // Keep the selection in view, scrolling by whole rows.
    if (this.selected < this.first) this.first = this.selected;
    else if (this.selected >= this.first + VISIBLE_LINES) {
      this.first = this.selected - VISIBLE_LINES + 1;
    }
    this.first = Math.max(0, Math.min(this.first, Math.max(0, this.items.length - VISIBLE_LINES)));

    const visible = this.items.slice(this.first, this.first + VISIBLE_LINES);

    this.highlight.clear();
    const selectedRow = this.selected - this.first;
    if (selectedRow >= 0 && selectedRow < visible.length) {
      this.highlight
        .rect(0, selectedRow * LINE_HEIGHT - 1, VIEW_WIDTH, LINE_HEIGHT)
        .fill(SELECTION_COLOUR);
    }

    visible.forEach((item, index) => {
      let row = this.rows[index];
      if (!row) {
        row = new BitmapText('', { colour: BODY_TEXT_COLOUR });
        row.position.set(MARGIN, index * LINE_HEIGHT);
        this.rows.push(row);
        this.layer.addChild(row);
      }
      row.visible = true;
      row.text = clip(item, BODY_WIDTH - SCROLLBAR_WIDTH);
      row.tintColour = index === selectedRow ? SELECTION_TEXT_COLOUR : BODY_TEXT_COLOUR;
    });
    for (let i = visible.length; i < this.rows.length; i++) this.rows[i]!.visible = false;

    this.chrome.setScroll(this.first, this.items.length);
  }
}

/**
 * The body of a `Form`: `append`ed strings, wrapped and scrollable. The original's forms
 * scroll with the same keys the list navigates with, so `scroll(±1)` is what UP and DOWN
 * do here too.
 */
export class FormBody {
  private readonly rows: BitmapText[] = [];

  private readonly layer = new Container();

  private lines: string[] = [];

  private first = 0;

  constructor(private readonly chrome: Chrome) {
    chrome.body.addChild(this.layer);
  }

  get lineCount(): number {
    return this.lines.length;
  }

  get scrollTop(): number {
    return this.first;
  }

  /** `Form.append` for each paragraph, joined by a blank line as `a.a(boolean)` does. */
  setParagraphs(paragraphs: readonly string[]): void {
    this.lines = [];
    paragraphs.forEach((paragraph, index) => {
      if (index > 0) this.lines.push('');
      this.lines.push(...wrapText(paragraph, BODY_WIDTH - SCROLLBAR_WIDTH));
    });
    this.first = 0;
    this.refresh();
  }

  scroll(delta: number): void {
    const max = Math.max(0, this.lines.length - VISIBLE_LINES);
    const next = Math.min(max, Math.max(0, this.first + delta));
    if (next === this.first) return;
    this.first = next;
    this.refresh();
  }

  private refresh(): void {
    const visible = this.lines.slice(this.first, this.first + VISIBLE_LINES);
    visible.forEach((line, index) => {
      let row = this.rows[index];
      if (!row) {
        row = new BitmapText('', { colour: BODY_TEXT_COLOUR });
        row.position.set(MARGIN, index * LINE_HEIGHT);
        this.rows.push(row);
        this.layer.addChild(row);
      }
      row.visible = true;
      row.text = line;
    });
    for (let i = visible.length; i < this.rows.length; i++) this.rows[i]!.visible = false;

    this.chrome.setScroll(this.first, this.lines.length);
  }
}
