/**
 * T10 — the instructions, `a.b()`.
 *
 * Six `Form.append` calls, `c.a(1)` through `c.a(6)`, in file order — which is why T5
 * named those six strings `HELP_GOAL`, `HELP_KEYS`, `HELP_SPIKES`, `HELP_SIZE`,
 * `HELP_CRYSTALS` and `HELP_BOOSTS`. A MIDP `Form` lays them out and scrolls them; here
 * `FormBody` wraps them at the body width and UP/DOWN move a line at a time.
 *
 * `HELP_KEYS` reads "Use key 4 to move the ball left, key 6 to move the ball right and
 * key 2 to bounce the ball." That text is shipped, not generated, so the port cannot
 * rewrite it for a keyboard — which is precisely why `src/core/Input.ts` binds `Digit4`,
 * `Digit6` and `Digit2` alongside the arrows. The screen stays true either way.
 */
import type { StringKey } from '../core/I18n';
import { MenuState } from './MenuState';
import { GameState } from './StateMachine';
import { FormBody, buildChrome, type Chrome } from './ui';

/** `c.a(1)`..`c.a(6)`, in `a.b()`'s append order. */
export const HELP_KEYS: readonly StringKey[] = [
  'HELP_GOAL',
  'HELP_KEYS',
  'HELP_SPIKES',
  'HELP_SIZE',
  'HELP_CRYSTALS',
  'HELP_BOOSTS',
];

export class InstructionsState extends GameState {
  readonly name = 'instructions';

  private chrome!: Chrome;

  private body!: FormBody;

  override async enter(): Promise<void> {
    const { i18n } = this.ctx;

    this.chrome = buildChrome(this.view);
    this.chrome.setTitle(i18n.t('INSTRUCTIONS'));
    this.chrome.setSoftKeys(undefined, i18n.t('BACK'));

    this.body = new FormBody(this.chrome);
    this.body.setParagraphs(HELP_KEYS.map((key) => i18n.t(key)));
  }

  override tick(): void {
    for (const edge of this.ctx.input.poll()) {
      if (edge.type !== 'down') continue;
      if (edge.action === 'UP') this.body.scroll(-1);
      else if (edge.action === 'DOWN') this.body.scroll(1);
      else if (edge.action === 'BACK' || edge.action === 'SELECT') {
        void this.ctx.machine.replace(MenuState);
      }
    }
  }
}
