/**
 * T6 — the splash, ported from `d`'s `az`/`p`/`w` triple.
 *
 * `d`'s constructor sets `az = 1` and loads `as[az]`, where
 * `as = { "/icons/nokiagames.png", "/icons/bouncesplash.png" }`. Each tick, `d.a()` runs
 * the splash branch: while `p <= 30` it does `++p`, and when `p > 30` it advances the
 * `switch (az)` — `case 0` would load `as[1]`, and `case 1` sets `az = -1` and calls
 * `X.f()`, the menu. `d.keyPressed` short-circuits the wait with `p = 31`.
 *
 * **`az` is only ever assigned 1 (here) or -1 (`case 1`, and `a.f()`), so `case 0` — the
 * "Nokia Games" logo — is dead code in this build.** The splash is `bouncesplash.png`
 * alone, held for 32 ticks (p climbing 0 to 31 over 31 of them, then one more to trip the
 * `p > 30` test) which is 1.28 s at 40 ms, and any key cuts it to the next tick. PLAN.md
 * §T6 step 4 describes a two-image sequence; that is what the resource array implies, not
 * what the code does, so this state ships one image and `nokiagames.png` stays an
 * extracted asset with no call site. See docs/ORIGINAL.md.
 *
 * The draw is `graphics.fillRect(0, 0, 128, 128)` in black plus
 * `drawImage(w, ao >> 1, aw >> 1, HCENTER | VCENTER)`, so: black ground, image centred.
 *
 * ## T12: the splash is also the loading screen
 *
 * The MIDlet read its atlas, levels and tones out of the JAR when it wanted them. Over
 * HTTP that would put a stall between the menu and the first level, so the splash's 1.28
 * seconds are spent pulling the lot down (`core/Assets.preloadTasks`) and the state does
 * not leave until both the timer and the download are finished.
 *
 * **The bar only appears if it is needed.** On a warm cache the load finishes inside the
 * first tick or two and nothing is drawn — the splash looks exactly as it did in T6, which
 * is the point: a progress bar under the Bounce logo is a deviation, and one that flashes
 * for 40 ms is a worse deviation than one that stays for the two seconds it is telling you
 * something. `BAR_DELAY_TICKS` is that threshold.
 *
 * Any key still skips the wait, but only the timer half of it — there is no playing the
 * game before the atlas is in.
 */
import { Assets, Graphics, Sprite, Texture } from 'pixi.js';

import { BOOT_BUNDLE, Preloader, preloadTasks } from '../core/Assets';
import { VIEW_HEIGHT, VIEW_WIDTH } from '../core/Viewport';
import { GameState } from './StateMachine';
import { MenuState } from './MenuState';

/** `/icons/bouncesplash.png`, extracted to `assets/images/splash.png` by T2. */
export const SPLASH_IMAGE = 'images/splash.png';

/**
 * Ticks the splash is held for: `d.a()` increments `p` from 0 to 31 and then needs one
 * more tick to see `p > 30`. 32 x 40 ms = 1.28 s.
 */
export const SPLASH_TICKS = 32;

/** Ticks the load may take before the bar is drawn. 8 x 40 ms = 320 ms. */
export const BAR_DELAY_TICKS = 8;

/** The bar, in the 128x128 space: a thin line low on the splash, clear of the logo. */
export const BAR_Y = 118;
export const BAR_HEIGHT = 3;
export const BAR_MARGIN = 20;

/** Sampled from `bouncesplash.png`'s own palette, so the bar belongs to the image. */
const BAR_TRACK = 0x3b2410;
const BAR_FILL = 0xff9613;

export class SplashState extends GameState {
  readonly name = 'splash';

  private remaining = SPLASH_TICKS;

  private done = false;

  /** Ticks elapsed, for `BAR_DELAY_TICKS`. Counts up where `remaining` counts down. */
  private elapsed = 0;

  private loading = true;

  private progress = 0;

  private bar: Graphics | null = null;

  override async enter(): Promise<void> {
    await Assets.loadBundle(BOOT_BUNDLE);
    const texture: Texture = await Assets.load(SPLASH_IMAGE);
    // The upscale is integer, so `nearest` is the whole of the pixel-art story.
    texture.source.scaleMode = 'nearest';

    this.view.addChild(new Graphics().rect(0, 0, VIEW_WIDTH, VIEW_HEIGHT).fill(0x000000));

    const splash = new Sprite(texture);
    splash.anchor.set(0.5);
    // `HCENTER | VCENTER` about `(ao >> 1, aw >> 1)`.
    splash.position.set(VIEW_WIDTH >> 1, VIEW_HEIGHT >> 1);
    this.view.addChild(splash);

    this.bar = new Graphics();
    this.bar.visible = false;
    this.view.addChild(this.bar);

    // Not awaited: the splash is on screen while this runs, which is the whole idea.
    const preloader = new Preloader(preloadTasks(this.ctx.audio));
    void preloader
      .run((fraction) => {
        this.progress = fraction;
      })
      .then(() => {
        this.loading = false;
        for (const failure of preloader.failures) {
          console.error(`preload: ${failure.name} failed`, failure.error);
        }
      });
  }

  override tick(): void {
    if (this.done) return;
    this.elapsed++;

    // `d.keyPressed`'s `p = 31`: the press does not itself advance, the next tick does.
    for (const edge of this.ctx.input.poll()) {
      if (edge.type === 'down' && this.remaining > 1) this.remaining = 1;
    }

    if (this.remaining > 0) this.remaining--;

    // T12: the timer is necessary but no longer sufficient.
    if (this.remaining > 0 || this.loading) return;

    this.done = true;
    // `case 1: az = -1; M = false; X.f();`
    void this.ctx.machine.replace(MenuState);
  }

  override render(): void {
    const bar = this.bar;
    if (!bar) return;

    const wanted = this.loading && this.elapsed >= BAR_DELAY_TICKS;
    bar.visible = wanted;
    if (!wanted) return;

    const width = VIEW_WIDTH - 2 * BAR_MARGIN;
    bar.clear();
    bar.rect(BAR_MARGIN, BAR_Y, width, BAR_HEIGHT).fill(BAR_TRACK);
    // Whole virtual pixels: a fractional width is a half-lit pixel at every upscale.
    const filled = Math.round(width * Math.min(1, Math.max(0, this.progress)));
    if (filled > 0) bar.rect(BAR_MARGIN, BAR_Y, filled, BAR_HEIGHT).fill(BAR_FILL);
  }
}
