/**
 * T10 — the high-score screen, `a.c()`.
 *
 * ```java
 * public void c() {
 *     this.j = new Form(c.a(12));            // "High score"
 *     this.j.append(String.valueOf(this.h)); // the stored best, unpadded
 *     this.j.addCommand(this.d);             // Back
 *     ...
 * }
 * ```
 *
 * Note `String.valueOf(this.h)` and not `d.c(this.h)`: the HUD's zero padding is not
 * applied here, so a fresh profile shows a bare `0`. Reproduced.
 */
import { MenuState } from './MenuState';
import { GameState } from './StateMachine';
import { FormBody, buildChrome, type Chrome } from './ui';

export class HighScoreState extends GameState {
  readonly name = 'high-score';

  private chrome!: Chrome;

  private body!: FormBody;

  override async enter(): Promise<void> {
    const { i18n, session } = this.ctx;

    this.chrome = buildChrome(this.view);
    this.chrome.setTitle(i18n.t('HIGH_SCORE'));
    this.chrome.setSoftKeys(undefined, i18n.t('BACK'));

    this.body = new FormBody(this.chrome);
    this.body.setParagraphs([String(session.highScore)]);
  }

  override tick(): void {
    for (const edge of this.ctx.input.poll()) {
      if (edge.type !== 'down') continue;
      // The form is one line long; the scroll keys are wired anyway, for the day a
      // translated title pushes it over.
      if (edge.action === 'UP') this.body.scroll(-1);
      else if (edge.action === 'DOWN') this.body.scroll(1);
      else if (edge.action === 'BACK' || edge.action === 'SELECT') {
        void this.ctx.machine.replace(MenuState);
      }
    }
  }
}
