/**
 * T12 — optional tilt steering.
 *
 * PLAN.md §T12 lists tilt as optional, and it stays optional: off unless `?tilt=1`, and
 * even then it only ever produces `LEFT`/`RIGHT`. The bounce cannot be a gesture — `e.b()`
 * reads the up bit every tick and a jerk of the wrist is neither held nor released — so
 * the touch pad's bounce button stays on screen and tilt replaces the two steering ones.
 *
 * `DeviceOrientationEvent.gamma` is the roll about the screen's long axis, in degrees:
 * negative rolling left, positive rolling right, and useless past about +-70 where the
 * phone is on its side and the axis flips. The mapping is therefore a dead zone, a hard
 * edge, and a clamp:
 *
 *   |gamma| < DEAD_ZONE      no action (a hand is never level)
 *   |gamma| > TILT_LIMIT     ignored (the phone is past vertical; gamma wraps)
 *   otherwise                LEFT or RIGHT, held for as long as the tilt holds
 *
 * There is no analogue axis to feed: `e.b()` accelerates by a fixed `RUN_ACCEL` while the
 * bit is set, so a 5-degree tilt and a 40-degree one are the same input. Hysteresis on the
 * dead zone (`RELEASE_ZONE` is smaller than `DEAD_ZONE`) keeps a hand hovering on the
 * boundary from chattering the bit on and off at 60 Hz.
 *
 * In landscape the device's gamma no longer points across the screen, so
 * `screen.orientation.angle` rotates the reading — a phone held sideways still steers the
 * way it is tipped.
 *
 * iOS 13+ needs `DeviceOrientationEvent.requestPermission()` from inside a user gesture,
 * which is the same gesture that unlocks WebAudio; `enable()` is safe to call from there
 * and safe to call twice.
 */
import type { Action, Input } from './Input';

/** Degrees of roll before steering starts. */
export const DEAD_ZONE = 8;

/** Degrees it must fall back to before steering stops. Hysteresis; must be < DEAD_ZONE. */
export const RELEASE_ZONE = 4;

/** Past this the phone is near vertical and `gamma` stops meaning what it says. */
export const TILT_LIMIT = 70;

export type TiltReading = {
  /** `DeviceOrientationEvent.gamma`, degrees. */
  gamma: number | null;
  /** `DeviceOrientationEvent.beta`, degrees — used once the screen is rotated. */
  beta: number | null;
  /** `screen.orientation.angle`: 0, 90, 180 or 270. */
  angle: number;
};

/**
 * The steering axis in degrees, with the screen's rotation taken out. Pure, and the only
 * part of tilt worth a test.
 */
export function tiltAxis(reading: TiltReading): number | null {
  const { gamma, beta } = reading;
  if (gamma === null && beta === null) return null;
  const g = gamma ?? 0;
  const b = beta ?? 0;
  switch (((reading.angle % 360) + 360) % 360) {
    case 90:
      return -b;
    case 180:
      return -g;
    case 270:
      return b;
    default:
      return g;
  }
}

/**
 * Which action a reading holds, given what is held now. `held` is what makes the dead
 * zone hysteretic: an action already on survives down to `RELEASE_ZONE`.
 */
export function tiltAction(axis: number | null, held: Action | null): Action | null {
  if (axis === null || !Number.isFinite(axis)) return null;
  const magnitude = Math.abs(axis);
  if (magnitude > TILT_LIMIT) return null;
  const threshold = held === null ? DEAD_ZONE : RELEASE_ZONE;
  if (magnitude < threshold) return null;
  return axis < 0 ? 'LEFT' : 'RIGHT';
}

type OrientationSource = { angle: number } | null;

/** The permission gate iOS adds to `DeviceOrientationEvent`. */
type PermissionCtor = { requestPermission?: () => Promise<'granted' | 'denied' | 'default'> };

export class Tilt {
  private readonly input: Input;

  private attached = false;

  private held: Action | null = null;

  private orientation: OrientationSource = null;

  constructor(input: Input) {
    this.input = input;
  }

  /** True once readings are arriving and steering the ball. */
  get active(): boolean {
    return this.attached;
  }

  /**
   * Ask for permission where it is needed and start listening. Call from a user gesture.
   * Resolves to whether tilt is now running; a denial is not an error.
   */
  async enable(): Promise<boolean> {
    if (this.attached) return true;
    if (typeof window === 'undefined' || !('DeviceOrientationEvent' in window)) return false;

    const ctor = window.DeviceOrientationEvent as unknown as PermissionCtor;
    if (typeof ctor.requestPermission === 'function') {
      try {
        if ((await ctor.requestPermission()) !== 'granted') return false;
      } catch {
        return false; // not a gesture, or the user dismissed it
      }
    }

    this.orientation =
      (screen as unknown as { orientation?: { angle: number } }).orientation ?? null;
    window.addEventListener('deviceorientation', this.onOrientation);
    this.attached = true;
    return true;
  }

  disable(): void {
    if (!this.attached) return;
    window.removeEventListener('deviceorientation', this.onOrientation);
    this.attached = false;
    this.releaseHeld();
  }

  /** Drop the steering bit — for a pause, or when the pad takes over. */
  releaseHeld(): void {
    if (!this.held) return;
    this.input.release(this.held);
    this.held = null;
  }

  private readonly onOrientation = (event: Event): void => {
    const reading = event as DeviceOrientationEvent;
    const axis = tiltAxis({
      gamma: reading.gamma,
      beta: reading.beta,
      angle: this.orientation?.angle ?? 0,
    });
    const next = tiltAction(axis, this.held);
    if (next === this.held) return;
    if (this.held) this.input.release(this.held);
    this.held = next;
    if (next) this.input.press(next);
  };
}
