/**
 * T10 — the `Level %U completed!` screen, `a.d()`.
 *
 * ```java
 * public void d() {
 *     this.v.h();                   // stop the timer
 *     a(false, 0);                  // ... which restarts it, and sets M = 1
 *     this.M = 5;
 *     if (this.N == null) this.N = new Command(c.a(9), 4, 1);   // "Continue"
 *     this.j = new Form("");                                    // no title
 *     this.j.append(this.v.av);                                 // "Level %U completed!"
 *     this.j.append("\n\n");
 *     this.j.append("" + this.E + "\n");                        // the running score
 *     this.j.addCommand(this.N);
 *     ...
 * }
 * ```
 *
 * Three oddities, all reproduced:
 *
 * - **The form has an empty title.** Every other screen names itself; this one does not.
 * - **`a(false, 0)` is called for its side effects only.** With `z == false` it skips
 *   `v.a(i, 0, 3)` entirely and just restarts the canvas timer and sets it current — so
 *   for the instant before `m.setCurrent(this.j)` the game is technically running. The
 *   port has no such window: the level is already loaded by the time this screen is up.
 * - **`av` was formatted when the level *loaded*.** `b.a(int)` builds `S` and `av` from
 *   `ak` at load time, and `d.a()`'s tail increments `ak` before calling `X.d()`. So the
 *   number on this screen is the level you **just finished**, one behind `ak` — which is
 *   why `Session.level` is already the next level here and the text takes `level - 1`.
 *
 * The `Continue` command starts the next level: `a.commandAction`'s `N` arm sets `M = 1`
 * and makes the canvas current, and the canvas's `this.e` flag — set by `d.a()`'s tail —
 * makes its next tick call `j()`, which loads `ak`.
 */
import { MenuState } from './MenuState';
import { MODE_PLAYING } from '../game/Session';
import { PlayState } from './PlayState';
import { GameState } from './StateMachine';
import { FormBody, buildChrome, type Chrome } from './ui';

export class LevelCompleteState extends GameState {
  readonly name = 'level-complete';

  private chrome!: Chrome;

  private body!: FormBody;

  override async enter(): Promise<void> {
    const { i18n, session } = this.ctx;

    this.chrome = buildChrome(this.view);
    // `new Form("")` — the title really is empty.
    this.chrome.setTitle('');
    this.chrome.setSoftKeys(i18n.t('CONTINUE'), undefined);

    this.body = new FormBody(this.chrome);
    this.body.setParagraphs([
      i18n.t('LEVEL_COMPLETED', [String(session.level - 1)]),
      String(session.finalScore),
    ]);
  }

  override tick(): void {
    for (const edge of this.ctx.input.poll()) {
      if (edge.type !== 'down') continue;
      if (edge.action === 'SELECT' || edge.action === 'UP') {
        // `case this.N: this.M = 1; this.m.setCurrent(this.v);`
        this.ctx.session.mode = MODE_PLAYING;
        void this.ctx.machine.replace(PlayState);
        return;
      }
      // The original attaches no Back command here. A browser tab with no soft keys
      // needs a way out of a screen, and the menu still offers `Continue`.
      if (edge.action === 'BACK') void this.ctx.machine.replace(MenuState);
    }
  }
}
