/**
 * T6 — the fixed-timestep simulation clock, replacing class `f`.
 *
 * Class `f` is four lines of substance: it extends `TimerTask`, and its constructor does
 * `new Timer().schedule(this, 0L, 40L)` so that `run()` — a bare `b.k()` — fires every
 * **40 ms**. That is the whole of the original's timing model: 25 simulation steps a
 * second, no delta, no interpolation, integer physics advanced once per step.
 *
 * So the web port does not scale physics by a frame delta. `Loop` accumulates real time
 * and calls `step()` a whole number of times, leaving rendering to run at whatever rate
 * the browser offers:
 *
 *   const loop = new Loop((tick) => machine.tick(tick));
 *   app.ticker.add((ticker) => {
 *     loop.advance(ticker.deltaMS);
 *     machine.render(loop.alpha);
 *   });
 *
 * `Timer.schedule` is *fixed-delay*, not fixed-rate: a handset that fell behind simply
 * ran the game in slow motion rather than replaying missed ticks. We cannot do that
 * (a backgrounded tab would bank minutes of simulation), so time beyond
 * `maxCatchUpTicks` is dropped — the same visible outcome as the handset stalling,
 * without the catch-up burst. T12 additionally pauses on `visibilitychange`, which is
 * where most of the dropped time would otherwise come from.
 */

/** The original's timer period, in milliseconds — `f`'s `Timer.schedule(this, 0, 40)`. */
export const TICK_MS = 40;

/** 25 Hz. Every duration in class `d`/`e` counted in ticks converts through this. */
export const TICKS_PER_SECOND = 1000 / TICK_MS;

/**
 * How much simulation one `advance()` may run. Five ticks is 200 ms — enough to ride out
 * a dropped frame or a GC pause, short enough that a long stall never turns into a
 * fast-forward the player did not ask for.
 */
export const MAX_CATCH_UP_TICKS = 5;

export type LoopOptions = {
  /** Simulation period in ms. Defaults to the original's 40. */
  tickMs?: number;
  /** Ticks per `advance()` before surplus time is discarded. Defaults to 5. */
  maxCatchUpTicks?: number;
};

export class Loop {
  /** Milliseconds of real time not yet turned into a tick. */
  private accumulator = 0;

  private ticks = 0;

  private dropped = 0;

  private readonly step: (tick: number) => void;

  private readonly tickMs: number;

  private readonly maxCatchUpTicks: number;

  constructor(step: (tick: number) => void, options: LoopOptions = {}) {
    this.step = step;
    this.tickMs = options.tickMs ?? TICK_MS;
    this.maxCatchUpTicks = options.maxCatchUpTicks ?? MAX_CATCH_UP_TICKS;
  }

  /** Ticks run since construction or the last `reset()` — the original's frame counter. */
  get tick(): number {
    return this.ticks;
  }

  /** Simulation period in ms, for callers converting tick counts to seconds. */
  get period(): number {
    return this.tickMs;
  }

  /**
   * Fraction of the way from the last tick to the next, in `[0, 1)`. Renderers may use
   * it to interpolate; nothing in the parity path does, because the original had no such
   * notion and interpolating a 12px tile grid at 25 Hz reads as blur, not smoothness.
   */
  get alpha(): number {
    return this.accumulator / this.tickMs;
  }

  /** Ticks' worth of time thrown away by the catch-up clamp. Non-zero means we stalled. */
  get droppedTicks(): number {
    return this.dropped;
  }

  /** Drop banked time without running it. Use after a pause, a level load, or a resume. */
  reset(): void {
    this.accumulator = 0;
  }

  /**
   * Feed real elapsed time in. Returns how many times `step()` ran, which is 0 on most
   * frames at 60 Hz (40 ms of simulation per 16.7 ms frame means a tick every ~2.4).
   */
  advance(elapsedMs: number): number {
    if (!Number.isFinite(elapsedMs) || elapsedMs <= 0) return 0;

    this.accumulator += elapsedMs;

    // Clamp before stepping, so a stall costs the player nothing but the stall itself.
    const budget = this.maxCatchUpTicks * this.tickMs;
    if (this.accumulator > budget) {
      this.dropped += Math.floor((this.accumulator - budget) / this.tickMs);
      this.accumulator = budget;
    }

    let ran = 0;
    while (this.accumulator >= this.tickMs) {
      this.accumulator -= this.tickMs;
      this.ticks++;
      ran++;
      this.step(this.ticks);
    }
    return ran;
  }
}
