/**
 * T5 — the localization runtime, replacing class `c`.
 *
 * The MIDlet picks its table from the `microedition.locale` system property, falls back
 * to `lang.xx` when there is no file for it, and looks strings up by a bare index. The
 * web port keeps the behaviour and drops the indices: `tools/decode-lang.ts` turns each
 * `/lang.<locale>` into `assets/i18n/<locale>.json` keyed by the names below, which come
 * from the call sites in classes `a` and `b`.
 *
 *   const i18n = await I18n.load();          // navigator.languages, else English
 *   i18n.t('LEVEL');                         // "Level %U"
 *   i18n.t('LEVEL', [String(n)]);            // "Level 3"
 *
 * See docs/ORIGINAL.md for the file format and the index -> name mapping's evidence.
 */

/**
 * The 19 strings, in file order — the index of a key here *is* the index class `c` reads.
 * Names are derived from the English text and from what each call site does with it.
 */
export const STRING_KEYS = [
  /** 0 — `new List(c.a(0), IMPLICIT)`, the main menu's title. */
  'TITLE',
  /** 1..6 — the six paragraphs `a.b()` appends to the Instructions form, in order. */
  'HELP_GOAL',
  'HELP_KEYS',
  'HELP_SPIKES',
  'HELP_SIZE',
  'HELP_CRYSTALS',
  'HELP_BOOSTS',
  /** 7 — `a.d`, the Back command on the score/help/level forms. */
  'BACK',
  /** 8 — shown by `a.a(true)` after level 011. */
  'CONGRATS',
  /** 9 — menu item 0, present only mid-game; also the command on the level-done form. */
  'CONTINUE',
  /** 10 — `a.k`, the menu's Exit command. */
  'EXIT',
  /** 11 — title *and* body of the `a.a(false)` form. */
  'GAME_OVER',
  /** 12 — menu item and the title of the high-score form. */
  'HIGH_SCORE',
  /** 13 — menu item and the title of the instructions form. */
  'INSTRUCTIONS',
  /** 14 — `b.S`, the HUD/level-select label. Takes the level number. */
  'LEVEL',
  /** 15 — `b.av`, shown by `a.d()` between levels. Takes the level number. */
  'LEVEL_COMPLETED',
  /** 16 — menu item, and the title of the level-select list in `a.g()`. */
  'NEW_GAME',
  /** 17 — appended by `a.a()` when `mNewBestScore`. */
  'NEW_HIGH_SCORE',
  /** 18 — `a.i`, the OK command on the game-over/congrats form. */
  'OK',
] as const;

export type StringKey = (typeof STRING_KEYS)[number];

/**
 * The six tables shipped in the JAR. `xx` is the English fallback the MIDlet reaches for
 * when there is no file matching `microedition.locale`.
 */
export const LOCALES = ['xx', 'de', 'fr', 'hu-HU', 'pl-PL', 'ro-RO'] as const;

export type Locale = (typeof LOCALES)[number];

export const FALLBACK_LOCALE: Locale = 'xx';

/** One decoded `assets/i18n/<locale>.json`. */
export type LangJson = {
  locale: Locale;
  source: string;
  strings: Record<StringKey, string>;
};

const I18N_BASE = 'i18n';

/**
 * Port of `c.a(String, String, String)`: replaces the **first** occurrence only, and
 * returns the subject untouched when the placeholder is absent. Both details matter —
 * `String.replaceAll` would diverge on a template that repeats a placeholder.
 */
function replaceFirst(subject: string, needle: string, value: string): string {
  const at = subject.indexOf(needle);
  return at >= 0 ? subject.slice(0, at) + value + subject.slice(at + needle.length) : subject;
}

/**
 * Port of the argument substitution at the end of `c.a(int, String[])`: one argument
 * fills `%U`, several fill `%0U`, `%1U`, ... Every shipped string uses the one-argument
 * form, but the two-form rule is the original's, so keep it.
 */
export function format(template: string, args?: readonly string[]): string {
  if (!args || args.length === 0) return template;
  if (args.length === 1) return replaceFirst(template, '%U', args[0]!);
  let out = template;
  for (let index = 0; index < args.length; index++)
    out = replaceFirst(out, `%${index}U`, args[index]!);
  return out;
}

/** True when `value` names one of the shipped tables. */
export function isLocale(value: string): value is Locale {
  return (LOCALES as readonly string[]).includes(value);
}

/**
 * Resolve BCP-47 tags from the browser to a shipped table, mirroring the MIDlet's
 * "try `/lang.<locale>`, else `/lang.xx`" with one addition: `microedition.locale` was
 * already in the file's own shape (`de`, `hu-HU`), whereas `navigator.language` gives
 * `de-DE` or `de-AT`, so a region-tagged tag also gets tried by its base language.
 * Matching is case-insensitive because `navigator.language` casing is not guaranteed.
 */
export function pickLocale(tags: readonly string[] = navigatorLanguages()): Locale {
  for (const tag of tags) {
    const normalized = normalizeTag(tag);
    if (!normalized) continue;
    const base = normalized.split('-')[0]!;
    for (const candidate of [normalized, base]) {
      const hit = LOCALES.find((locale) => locale.toLowerCase() === candidate);
      if (hit) return hit;
    }
  }
  return FALLBACK_LOCALE;
}

function normalizeTag(tag: string): string {
  return tag.trim().toLowerCase().replace(/_/g, '-');
}

function navigatorLanguages(): readonly string[] {
  if (typeof navigator === 'undefined') return [];
  return navigator.languages?.length ? navigator.languages : [navigator.language];
}

/**
 * A loaded table plus the English fallback. A key missing from a translated file falls
 * back to English and then to the key itself — the UI showing `NEW_HIGH_SCORE` is far
 * better than a thrown exception mid-level.
 */
export class I18n {
  readonly locale: Locale;

  private readonly strings: Partial<Record<StringKey, string>>;

  private readonly fallback: Partial<Record<StringKey, string>>;

  constructor(table: LangJson, fallback?: LangJson) {
    this.locale = table.locale;
    this.strings = table.strings ?? {};
    this.fallback = fallback?.strings ?? {};
  }

  /**
   * Fetch the table for `locale` (default: the browser's), plus English when that is a
   * different file.
   */
  static async load(locale: Locale = pickLocale()): Promise<I18n> {
    const table = await fetchLang(locale);
    if (locale === FALLBACK_LOCALE) return new I18n(table);
    return new I18n(table, await fetchLang(FALLBACK_LOCALE));
  }

  /** Look a string up and substitute its arguments. Never throws. */
  t(key: StringKey, args?: readonly string[]): string {
    return format(this.strings[key] ?? this.fallback[key] ?? key, args);
  }

  /** True when the active table carries its own text for `key`. */
  has(key: StringKey): boolean {
    return this.strings[key] !== undefined;
  }
}

async function fetchLang(locale: Locale): Promise<LangJson> {
  const response = await fetch(`${I18N_BASE}/${locale}.json`);
  if (!response.ok) throw new Error(`cannot load lang "${locale}": HTTP ${response.status}`);
  return (await response.json()) as LangJson;
}
