/**
 * T6/T12 — abstract input actions, replacing `d.keyPressed`/`d.keyReleased`.
 *
 * The original's handling is a switch on the raw MIDP key code with a fall-through to
 * `Canvas.getGameAction(n)`, and the actions it recognises are:
 *
 * | game action | code in `d` | effect |
 * | --- | --- | --- |
 * | `UP` (1)    | `aA.c(8)` / `aA.a(8)` | the bounce |
 * | `LEFT` (2)  | `aA.c(1)` / `aA.a(1)` | move left |
 * | `RIGHT` (5) | `aA.c(2)` / `aA.a(2)` | move right |
 * | `DOWN` (6)  | `aA.c(4)` / `aA.a(4)` | move down |
 * | `FIRE` (8)  | `this.f = true`       | cheat-gated level skip, ignored here |
 *
 * plus the two soft keys (`-6`, `-7`) which return to the menu, and the digit keys
 * 1/3/7/8/9/# which are the debug and cheat paths (`an`, `h`, `B`). On the handset keys
 * 2/4/6 reach the ball only *through* `getGameAction`, which is why PLAN.md §T6 calls
 * them the movement keys — this port binds them directly as well as the arrows.
 *
 * `e.c()` sets a bit and `e.a()` clears it, so held keys are state, not events. Both are
 * exposed: `isDown()` for the ball, `poll()` for the edges menus and the splash need.
 *
 * There is deliberately no `JUMP` action distinct from `UP`. In the original they are the
 * same game action, and a menu reading `UP` as "previous item" while play reads it as
 * "bounce" is exactly how classes `a` and `d` already split that key.
 *
 * T12 makes the source of an action irrelevant: `press()`/`release()` are public, so a
 * key, a thumb on `core/TouchPad` and a tilt reading all set the same bit, and
 * `setHeldListener()` lets the pad light up for any of them.
 */

export type Action = 'LEFT' | 'RIGHT' | 'UP' | 'DOWN' | 'SELECT' | 'PAUSE' | 'BACK';

export const ACTIONS: readonly Action[] = [
  'LEFT',
  'RIGHT',
  'UP',
  'DOWN',
  'SELECT',
  'PAUSE',
  'BACK',
];

/** Readability alias: the bounce is game action `UP`, and `e.c(8)` is what it calls. */
export const JUMP: Action = 'UP';

/**
 * The bits `e.c(int)`/`e.a(int)` set and clear in the ball's direction mask, read
 * straight off the four call sites in `d.keyPressed`. T8 needs these; they live here
 * because this is where the key that sets them is named.
 */
export const DIRECTION_BIT = {
  LEFT: 1,
  RIGHT: 2,
  DOWN: 4,
  UP: 8,
} as const;

/**
 * `KeyboardEvent.code` to action. `code` rather than `key`, so the bindings survive a
 * non-QWERTY layout and `KeyW` does not become `KeyZ` on AZERTY.
 *
 * Arrows and WASD are the web conventions; the digits are the handset's own keys, kept
 * because the Instructions screen shows "Use key 4 to move the ball left..." verbatim and
 * that should not be a lie on a desktop keyboard. Digit 8 is *not* bound to `DOWN`:
 * `d.keyPressed` intercepts `'8'` for the cheat sequence before `getGameAction` sees it.
 */
export const KEY_BINDINGS: Readonly<Record<string, Action>> = {
  ArrowLeft: 'LEFT',
  KeyA: 'LEFT',
  Digit4: 'LEFT',
  Numpad4: 'LEFT',

  ArrowRight: 'RIGHT',
  KeyD: 'RIGHT',
  Digit6: 'RIGHT',
  Numpad6: 'RIGHT',

  ArrowUp: 'UP',
  KeyW: 'UP',
  Space: 'UP',
  Digit2: 'UP',
  Numpad2: 'UP',

  ArrowDown: 'DOWN',
  KeyS: 'DOWN',

  Enter: 'SELECT',
  NumpadEnter: 'SELECT',
  Digit5: 'SELECT',
  Numpad5: 'SELECT',

  KeyP: 'PAUSE',

  Escape: 'BACK',
  Backspace: 'BACK',
};

/** Resolve one `KeyboardEvent.code`. Unbound codes are left to the browser. */
export function actionForCode(code: string): Action | undefined {
  return KEY_BINDINGS[code];
}

export type InputEdge = { action: Action; type: 'down' | 'up' };

/**
 * T12 — where a touch lands is `core/TouchPad`'s business, not this file's. T6 had a stub
 * three-column zone table over the play area here; the real controls are circles in a
 * reserved band measured in CSS pixels, so `attachPointer` now takes a hit test instead
 * of owning one. Everything below stays source-agnostic: a key, a thumb and a tilt all
 * arrive as the same held action.
 */

/** Enough of `Viewport` for `attachPointer` to place a touch on the canvas. */
export type PointerMapper = {
  toCanvas(clientX: number, clientY: number): { x: number; y: number };
};

/** Canvas-space hit test — `TouchPad.actionAt`. */
export type PointerHitTest = (x: number, y: number) => Action | undefined;

/** Told whenever an action's held state changes, whatever pressed it. */
export type HeldListener = (action: Action, held: boolean) => void;

/** Past this the queue is dropping edges anyway; a stuck listener should not grow it. */
const MAX_QUEUED_EDGES = 64;

const NO_EDGES: readonly InputEdge[] = [];

export class Input {
  private readonly held = new Set<Action>();

  private queue: InputEdge[] = [];

  /** Which action each live pointer id holds, so `pointerup` releases the right one. */
  private readonly pointers = new Map<number, Action>();

  private keyTarget: EventTarget | null = null;

  private pointerTarget: EventTarget | null = null;

  private mapper: PointerMapper | null = null;

  private hitTest: PointerHitTest | null = null;

  private heldListener: HeldListener | null = null;

  /** Bind the keyboard. Calling twice is a no-op; `detach()` unbinds. */
  attach(target: EventTarget = window): void {
    if (this.keyTarget) return;
    this.keyTarget = target;
    target.addEventListener('keydown', this.onKeyDown);
    target.addEventListener('keyup', this.onKeyUp);
    target.addEventListener('blur', this.onBlur);
  }

  /**
   * Bind the touch pad. `mapper` is the `Viewport` (canvas-space, since the buttons are
   * measured in CSS pixels) and `hitTest` is `TouchPad.actionAt`, so a tap that lands on
   * no button — the letterbox, the play area itself — resolves to no action at all.
   */
  attachPointer(target: EventTarget, mapper: PointerMapper, hitTest: PointerHitTest): void {
    if (this.pointerTarget) return;
    this.pointerTarget = target;
    this.mapper = mapper;
    this.hitTest = hitTest;
    target.addEventListener('pointerdown', this.onPointerDown);
    target.addEventListener('pointermove', this.onPointerMove);
    target.addEventListener('pointerup', this.onPointerUp);
    target.addEventListener('pointercancel', this.onPointerUp);
  }

  /**
   * Watch held state. `TouchPad` uses it to light a button up, and it fires for the
   * keyboard too — pressing the arrow key highlights the on-screen arrow, which is how
   * you tell at a glance that a phone is receiving a Bluetooth keyboard.
   */
  setHeldListener(listener: HeldListener | null): void {
    this.heldListener = listener;
  }

  detach(): void {
    if (this.keyTarget) {
      this.keyTarget.removeEventListener('keydown', this.onKeyDown);
      this.keyTarget.removeEventListener('keyup', this.onKeyUp);
      this.keyTarget.removeEventListener('blur', this.onBlur);
      this.keyTarget = null;
    }
    if (this.pointerTarget) {
      this.pointerTarget.removeEventListener('pointerdown', this.onPointerDown);
      this.pointerTarget.removeEventListener('pointermove', this.onPointerMove);
      this.pointerTarget.removeEventListener('pointerup', this.onPointerUp);
      this.pointerTarget.removeEventListener('pointercancel', this.onPointerUp);
      this.pointerTarget = null;
      this.mapper = null;
      this.hitTest = null;
    }
    this.clear();
  }

  /** Held state — the equivalent of a set bit in the ball's direction mask. */
  isDown(action: Action): boolean {
    return this.held.has(action);
  }

  /** True while anything is held. `d.keyPressed`'s "any key skips the splash". */
  get anyDown(): boolean {
    return this.held.size > 0;
  }

  /**
   * Take the edges seen since the last call. Called once per simulation tick, so a key
   * tapped and released inside one 40 ms tick still registers — the original could not
   * miss one either, its key callbacks ran between ticks on the UI thread.
   */
  poll(): readonly InputEdge[] {
    if (this.queue.length === 0) return NO_EDGES;
    const edges = this.queue;
    this.queue = [];
    return edges;
  }

  /**
   * Hold an action down from any source — a key, a thumb, a tilt. Repeats are ignored, so
   * a caller may assert the same state every frame; `Tilt` does exactly that.
   */
  press(action: Action): void {
    if (this.held.has(action)) return;
    this.held.add(action);
    this.push(action, 'down');
    this.heldListener?.(action, true);
  }

  /** Release an action held by `press()`. Releasing an idle action does nothing. */
  release(action: Action): void {
    if (!this.held.delete(action)) return;
    this.push(action, 'up');
    this.heldListener?.(action, false);
  }

  /** Forget held keys and queued edges, releasing each held one first. */
  clear(): void {
    for (const action of this.held) {
      this.push(action, 'up');
      this.heldListener?.(action, false);
    }
    this.held.clear();
    this.pointers.clear();
  }

  private push(action: Action, type: 'down' | 'up'): void {
    if (this.queue.length >= MAX_QUEUED_EDGES) return;
    this.queue.push({ action, type });
  }

  private readonly onKeyDown = (event: Event): void => {
    const key = event as KeyboardEvent;
    const action = actionForCode(key.code);
    if (!action) return;
    // Arrows and Space scroll the page; what we claim, we claim completely.
    key.preventDefault();
    // Auto-repeat is not an edge — the original had no key repeat to speak of.
    if (key.repeat) return;
    this.press(action);
  };

  private readonly onKeyUp = (event: Event): void => {
    const key = event as KeyboardEvent;
    const action = actionForCode(key.code);
    if (!action) return;
    key.preventDefault();
    this.release(action);
  };

  /** Losing focus mid-jump would otherwise leave a direction held forever. */
  private readonly onBlur = (): void => {
    this.clear();
  };

  private resolve(event: PointerEvent): Action | undefined {
    if (!this.mapper || !this.hitTest) return undefined;
    const point = this.mapper.toCanvas(event.clientX, event.clientY);
    return this.hitTest(point.x, point.y);
  }

  /** Release an action unless another live pointer is still on it. */
  private releaseIfLast(action: Action): void {
    for (const other of this.pointers.values()) if (other === action) return;
    this.release(action);
  }

  private readonly onPointerDown = (event: Event): void => {
    const pointer = event as PointerEvent;
    const action = this.resolve(pointer);
    if (!action) return;
    pointer.preventDefault();
    // A thumb that slides off the canvas must still get its `pointerup`.
    (pointer.target as Element | null)?.setPointerCapture?.(pointer.pointerId);
    this.pointers.set(pointer.pointerId, action);
    this.press(action);
  };

  /**
   * A thumb sliding from one button to the next swaps which is held. Only pointers that
   * started on a button are tracked, so a mouse crossing the pad presses nothing.
   */
  private readonly onPointerMove = (event: Event): void => {
    const pointer = event as PointerEvent;
    const previous = this.pointers.get(pointer.pointerId);
    if (previous === undefined) return;
    const action = this.resolve(pointer);
    if (action === previous) return;
    pointer.preventDefault();
    if (action) this.pointers.set(pointer.pointerId, action);
    else this.pointers.delete(pointer.pointerId);
    this.releaseIfLast(previous);
    if (action) this.press(action);
  };

  private readonly onPointerUp = (event: Event): void => {
    const pointer = event as PointerEvent;
    const action = this.pointers.get(pointer.pointerId);
    if (!action) return;
    this.pointers.delete(pointer.pointerId);
    // Two fingers can hold one button; only the last one up releases it.
    this.releaseIfLast(action);
  };
}
