/**
 * T10 — the main menu, `a.f()` and the `List.SELECT_COMMAND` half of `a.commandAction`.
 *
 * ```java
 * public synchronized void f() {
 *     this.c = new List(c.a(0), 3);                      // IMPLICIT, title "Bounce"
 *     if (this.d == null) {
 *         this.d = new Command(c.a(7), 2, 1);            // Back
 *         this.k = new Command(c.a(10), 7, 1);           // Exit
 *     }
 *     if (this.M == 1 || this.L == 1 || this.L == 2)
 *         this.c.append(this.x[0], null);                // Continue
 *     for (int i = 1; i < this.x.length; i++)
 *         this.c.append(this.x[i], null);                // New game / High score / Instructions
 *     this.c.addCommand(this.k);
 *     ...
 *     if (this.M == 1 || this.L == 1 || this.L == 2) this.c.setSelectedIndex(0, true);
 *     else this.c.setSelectedIndex(this.P, true);
 *     this.v.h();                                        // stop the 40 ms timer
 *     this.m.setCurrent(this.c);
 * }
 * ```
 *
 * `a.e()` fills `x` with `[CONTINUE, NEW_GAME, HIGH_SCORE, INSTRUCTIONS]` once, in the
 * constructor, and `a.commandAction` dispatches by **comparing the selected string to
 * those four** rather than by index — which is why the `Continue` row can appear and
 * disappear without renumbering anything. The port dispatches on the key instead; the
 * effect is the same and it does not break when two locales translate two items alike.
 *
 * Three details that are easy to lose:
 *
 * - **`P` remembers the last selection**, but only when `Continue` is absent; with a game
 *   in progress the highlight is forced to row 0. `P` is written on every selection, so
 *   it survives a trip into Instructions and back.
 * - **`New game` is ignored while `M == 4`** — the mode set by the very first `New game`
 *   on a save-less profile. It is a re-entrancy guard, and it means the item is inert
 *   exactly once, before the first level has been finished.
 * - **`Exit` from the menu destroys the MIDlet.** A browser tab cannot do that, so the
 *   port writes the save and says the game is over; see `exitGame()`.
 */
import type { StringKey } from '../core/I18n';
import { MODE_NEW_GAME, MODE_PLAYING } from '../game/Session';
import { HighScoreState } from './HighScoreState';
import { InstructionsState } from './InstructionsState';
import { LevelSelectState } from './LevelSelectState';
import { PlayState } from './PlayState';
import { GameState } from './StateMachine';
import { ListBody, buildChrome, type Chrome } from './ui';

/** `a.x`, in the order `a.e()` fills it. Index 0 is conditional; see `enter()`. */
export const ITEM_KEYS: readonly StringKey[] = [
  'CONTINUE',
  'NEW_GAME',
  'HIGH_SCORE',
  'INSTRUCTIONS',
];

/**
 * `a.P` — the remembered selection. Static because `a` is a single long-lived object and
 * `P` is one of its fields; a `MenuState` is rebuilt on every visit.
 */
let lastSelected = 0;

/** Reset the remembered selection. For tests, and for a cold start. */
export function resetMenuSelection(): void {
  lastSelected = 0;
}

/** The items `a.f()` would append, given a session. Pure, so the suite can check it. */
export function menuItems(canContinue: boolean): StringKey[] {
  return canContinue ? [...ITEM_KEYS] : ITEM_KEYS.slice(1);
}

export class MenuState extends GameState {
  readonly name = 'menu';

  private chrome!: Chrome;

  private list!: ListBody;

  private items: StringKey[] = [];

  override async enter(): Promise<void> {
    const { i18n, session } = this.ctx;

    this.chrome = buildChrome(this.view);
    this.chrome.setTitle(i18n.t('TITLE'));
    // `addCommand(this.k)` — Exit is the menu's only command. Selection is implicit.
    this.chrome.setSoftKeys(undefined, i18n.t('EXIT'));

    this.list = new ListBody(this.chrome);
    this.items = menuItems(session.canContinue);

    // `setSelectedIndex(0, true)` with a game in progress or a save; else `P`.
    const selected = session.canContinue ? 0 : Math.min(lastSelected, this.items.length - 1);
    this.list.setItems(
      this.items.map((key) => i18n.t(key)),
      selected,
    );
  }

  override tick(): void {
    for (const edge of this.ctx.input.poll()) {
      if (edge.type !== 'down') continue;
      if (edge.action === 'UP') this.list.move(-1);
      else if (edge.action === 'DOWN') this.list.move(1);
      else if (edge.action === 'SELECT') this.select();
      else if (edge.action === 'BACK') this.exitGame();
    }
  }

  private select(): void {
    const key = this.items[this.list.selected];
    if (!key) return;
    // `this.P = this.c.getSelectedIndex()`, before the dispatch.
    lastSelected = this.list.selected;

    const { session } = this.ctx;
    switch (key) {
      case 'CONTINUE':
        // `M == 1` resumes the level that is still running; otherwise load the save.
        if (session.mode === MODE_PLAYING || session.resumeSavedGame()) {
          session.mode = MODE_PLAYING;
          void this.ctx.machine.replace(PlayState);
        }
        return;
      case 'NEW_GAME':
        // `if (this.M != 4)` — inert on a profile that has never finished a level.
        if (session.mode === MODE_NEW_GAME) return;
        if (session.canSelectLevel) {
          void this.ctx.machine.replace(LevelSelectState);
        } else {
          session.mode = MODE_NEW_GAME;
          session.startNewGame(1);
          // `startNewGame` sets `M = 1`; `a.a(true, 1)` does the same, after `M = 4`.
          void this.ctx.machine.replace(PlayState);
        }
        return;
      case 'HIGH_SCORE':
        void this.ctx.machine.replace(HighScoreState);
        return;
      case 'INSTRUCTIONS':
        void this.ctx.machine.replace(InstructionsState);
        return;
      default:
        return;
    }
  }

  /**
   * `a.commandAction`'s Exit arm: `s.destroyApp(true); s.notifyDestroyed();`, which runs
   * `Bounce.destroyApp` and therefore `a.a(3)` — the save. A page cannot close itself, so
   * the port does the save and leaves the menu up. `window.close()` is not attempted: it
   * is a no-op for any tab the script did not open.
   */
  private exitGame(): void {
    this.ctx.session.save();
  }
}
