/**
 * T10 — the level picker, `a.g()`.
 *
 * ```java
 * public void g() {
 *     String[] strArr = new String[this.f];
 *     String[] strArr2 = new String[1];
 *     for (int i = 0; i < this.f; i++) {
 *         strArr2[0] = String.valueOf(i + 1);
 *         strArr[i] = c.a(14, strArr2);            // "Level %U"
 *     }
 *     this.F = new List(c.a(16), 3, strArr, null); // title "New game", IMPLICIT
 *     this.F.addCommand(this.d);                   // Back
 *     ...
 * }
 * ```
 *
 * `f` is the highest level *reached*, which `a.a()` sets from `d.ak` **after** `d.a()`
 * has already incremented it — so finishing level 1 sets `f = 2` and this list offers
 * levels 1 and 2. That is also why `a.commandAction` gates the whole screen on `f > 1`:
 * with `f` at 0 or 1 there is nothing to choose between, and `New game` starts level 1
 * directly.
 *
 * Selecting a row runs `a(true, index + 1)` — a fresh run at that level, score 0, three
 * lives, `mNewBestScore` cleared. Starting at level 7 and finishing it therefore banks a
 * score that never passed through levels 1-6, which is the original's rule and not a bug
 * to be fixed here.
 */
import { PlayState } from './PlayState';
import { MenuState } from './MenuState';
import { GameState } from './StateMachine';
import { ListBody, buildChrome, type Chrome } from './ui';

export class LevelSelectState extends GameState {
  readonly name = 'level-select';

  private chrome!: Chrome;

  private list!: ListBody;

  private levels = 0;

  override async enter(): Promise<void> {
    const { i18n, session } = this.ctx;

    this.chrome = buildChrome(this.view);
    this.chrome.setTitle(i18n.t('NEW_GAME'));
    this.chrome.setSoftKeys(undefined, i18n.t('BACK'));

    this.levels = session.unlockedLevels;
    this.list = new ListBody(this.chrome);
    this.list.setItems(
      Array.from({ length: this.levels }, (_, index) => i18n.t('LEVEL', [String(index + 1)])),
    );
  }

  override tick(): void {
    for (const edge of this.ctx.input.poll()) {
      if (edge.type !== 'down') continue;
      if (edge.action === 'UP') this.list.move(-1);
      else if (edge.action === 'DOWN') this.list.move(1);
      else if (edge.action === 'BACK') void this.ctx.machine.replace(MenuState);
      else if (edge.action === 'SELECT') {
        if (this.levels === 0) return;
        // `a(true, this.F.getSelectedIndex() + 1)`.
        this.ctx.session.startNewGame(this.list.selected + 1);
        void this.ctx.machine.replace(PlayState);
      }
    }
  }
}
