/**
 * T10 — the run in progress: class `a`'s fields, minus the `Displayable`s.
 *
 * Class `a` is two things at once, and only one of them is a controller. The other is a
 * bag of run state that outlives every screen — `M` (the mode), `f` (the highest level
 * reached), `h` (the high score), `q` (`mNewBestScore`), `E` (the score the end-of-game
 * form prints), plus the level, score and lives it hands to `d.a(int,int,int)`. The
 * screens in `src/states/` are short-lived; this is what they read and write between
 * themselves, and `StateMachine`'s `Services` carries it.
 *
 * The mode constants are `a.M`'s own values, because three separate decisions read them:
 *
 * - `a.f()` offers `CONTINUE` when `M == 1` — a game is running behind the menu — or when
 *   a save exists;
 * - `a.commandAction` sends `CONTINUE` back into the level (`M == 1`) rather than loading
 *   the save;
 * - `a.commandAction` ignores `NEW_GAME` entirely while `M == 4`.
 *
 * ## What is *not* ported, and why
 *
 * `a.a(3)` writes a 255-byte mid-level snapshot: the ball's pixel position and its five
 * physics registers, the camera, a table of up to 50 surviving collectible cells, and
 * every moving hazard's offset. `Bounce.destroyApp` is its only caller, so it is the "you
 * quit in the middle of level 7" save. Restoring it needs `Playfield` to be constructible
 * *from* that state rather than from a spawn tile, which is not something T8 gave it, and
 * `Storage.SavedGame` deliberately has no room for the cell table.
 *
 * So the port saves **kind 2** — `SAVE_LEVEL_START`, the same shape the original writes
 * from its level-complete screen — always: the level you were on, with the score and
 * lives you started it with. `CONTINUE` after a reload restarts that level. It is a
 * documented deviation, not an oversight; see docs/ORIGINAL.md.
 */
import { LEVEL_COUNT, SAVE_LEVEL_START, type Storage } from '../core/Storage.ts';
import { STARTING_LIVES } from './Physics.ts';
import type { Playfield } from './Playfield.ts';

/** `a.M == 1` — the canvas is current and a level is being played. */
export const MODE_PLAYING = 1;

/** `a.M == 2` — the value the field is initialised to, i.e. the splash. */
export const MODE_SPLASH = 2;

/** `a.M == 3` — set by `a.b(boolean)`, the game-over/congrats form. */
export const MODE_ENDED = 3;

/** `a.M == 4` — a brand new game, which is what suppresses a second `New game`. */
export const MODE_NEW_GAME = 4;

/** `a.M == 5` — the `Level %U completed!` form is up. */
export const MODE_LEVEL_DONE = 5;

/** `d.a()`'s `b(5000)` on the tick the door is entered. */
export const SCORE_LEVEL_COMPLETE = 5000;

/** Levels in the JAR. `d.a()` ends the game when `ak` passes it. */
export { LEVEL_COUNT } from '../core/Storage.ts';

export class Session {
  private readonly storage: Storage;

  /** `a.M`. */
  mode: number = MODE_SPLASH;

  /** `d.ak` — the level about to be played, or being played. 1-based. */
  level = 1;

  /** `d.g` — the score carried across levels. */
  score = 0;

  /** `d.j` — lives. `d.a(int,int,int)` is called with 3. */
  lives: number = STARTING_LIVES;

  /** `a.q` (`mNewBestScore`) — printed as `New high score!` on the end form. */
  newBestScore = false;

  /** `a.E` — the score the game-over and level-complete forms print. */
  finalScore = 0;

  /** True on the congrats path: the run finished level 011 rather than running out. */
  finished = false;

  /**
   * The level left running behind the menu. The MIDlet does not need this — `d` is one
   * long-lived `Canvas` and `X.f()` merely stops its timer — but a `StateMachine` state
   * is destroyed on exit, so the *simulation* is parked here while its view goes away.
   * `PlayState` picks it up when the level number still matches, which is exactly the
   * condition `a.commandAction`'s `M == 1` arm tests.
   */
  suspended: Playfield | null = null;

  constructor(storage: Storage) {
    this.storage = storage;
  }

  /** `a.f()`'s `M == 1 || L == 1 || L == 2`. */
  get canContinue(): boolean {
    return this.mode === MODE_PLAYING || this.storage.canContinue;
  }

  /** `a.g()`'s `f > 1`: the level-select list exists only once level 2 is unlocked. */
  get canSelectLevel(): boolean {
    return this.storage.highestLevel > 1;
  }

  /** Levels offered by `a.g()` — `for (i = 0; i < this.f; i++)`. */
  get unlockedLevels(): number {
    return Math.min(this.storage.highestLevel, LEVEL_COUNT);
  }

  get highScore(): number {
    return this.storage.highScore;
  }

  /** `a.a(true, level)` — a fresh run: score 0, three lives, `mNewBestScore` cleared. */
  startNewGame(level: number): void {
    this.level = Math.min(Math.max(1, Math.trunc(level)), LEVEL_COUNT);
    this.score = 0;
    this.lives = STARTING_LIVES;
    this.newBestScore = false;
    this.finished = false;
    this.suspended = null;
    this.mode = MODE_PLAYING;
    this.save();
  }

  /**
   * The `CONTINUE` menu item with no game running: `a.commandAction`'s `L != 0` arm.
   * Returns false when there is nothing to resume, which is the original's do-nothing.
   */
  resumeSavedGame(): boolean {
    const saved = this.storage.savedGame;
    if (!saved) return false;
    this.level = saved.level;
    this.score = saved.score;
    this.lives = saved.lives;
    this.newBestScore = false;
    this.finished = false;
    this.suspended = null;
    this.mode = MODE_PLAYING;
    return true;
  }

  /**
   * `a.a()` — commit the run to the record store and set the score the forms print.
   * Called by `d.a()` on a completed level and on the last death, in that order: the
   * level is banked before the score, and `q` latches for the whole run once set.
   */
  commit(): void {
    this.storage.recordLevelReached(this.level);
    if (this.storage.recordScore(this.score)) this.newBestScore = true;
    this.finalScore = this.score;
  }

  /**
   * `d.a()`'s tail, the `if (this.f)` arm: bank 5000, step the level, commit, and say
   * whether the run is over. `true` means the congrats form, `false` the level-complete
   * one.
   */
  completeLevel(): boolean {
    this.suspended = null;
    this.score += SCORE_LEVEL_COMPLETE;
    // `ak` is stepped *before* `X.a()`, so finishing level 1 banks `f = 2` and unlocks
    // the level-select list. Past 11 the same call clamps it back to 11.
    this.level += 1;
    this.commit();
    if (this.level > LEVEL_COUNT) {
      // `X.b(true)` — the congrats form, which is the game-over form with a nicer title.
      this.endGame(true);
      return true;
    }
    this.mode = MODE_LEVEL_DONE;
    this.save();
    return false;
  }

  /**
   * `d.a()`'s game-over arm — `X.a(); h(); X.b(false);` — and the congrats arm,
   * `X.b(true)`. `commit()` is idempotent, so `completeLevel()` calling it first and this
   * calling it again on the way past level 011 costs nothing.
   */
  endGame(congrats: boolean): void {
    this.commit();
    this.finished = congrats;
    // `a.b(boolean)`: `M = 3; L = 0` — the run is over, so there is nothing to continue.
    this.suspended = null;
    this.mode = MODE_ENDED;
    this.storage.clearSavedGame();
  }

  /**
   * `a.a(3)`, in the reduced form this port keeps. Written whenever the level, score or
   * lives change rather than only on exit, because a browser tab does not get a reliable
   * `destroyApp`.
   */
  save(): void {
    if (this.mode !== MODE_PLAYING && this.mode !== MODE_LEVEL_DONE) return;
    if (this.level > LEVEL_COUNT) return;
    this.storage.saveGame({
      kind: SAVE_LEVEL_START,
      savedAtMs: Date.now(),
      level: this.level,
      lives: this.lives,
      score: this.score,
      // Both are `SavedGame` fields the mid-level snapshot needs and a level-start one
      // does not: the resume respawns at the level's own spawn tile, so `Playfield` takes
      // the hoop count and the ball size from the level file, not from here.
      hoopsCollected: 0,
      ballSize: 12,
    });
  }
}
