/**
 * T6 — the screen stack, replacing `a.M` and `Display.setCurrent`.
 *
 * The original has no state machine as such. Class `a` keeps a mode integer `M` (2 on
 * startup, 1 while playing, 4 for a fresh game at level 1, 5 on the level-complete form)
 * and swaps `Displayable`s: a `List` for the menu, `Form`s for the score, instructions,
 * game-over and level-complete screens, and the `d` canvas for play. Every screen either
 * receives `commandAction` or, in `d`'s case, ticks off the shared timer.
 *
 * The web port keeps that shape but makes it explicit: one active state at a time, each
 * owning a `Container` and receiving the 25 Hz tick. Only one state is live because the
 * original never had two — `Display.setCurrent` is a replace, not a push, and even the
 * pause path (`d.hideNotify`) replaces the canvas with the menu rather than layering over
 * it — T12's `suspend()` hook is where that lands.
 *
 * States are constructed from a class, not passed in as instances, so a state can name
 * its successor without either having to reach for the context first:
 *
 *   machine.replace(SplashState);
 *
 * `enter()` may be async — a state that needs a texture should load it there rather than
 * pop up empty. While a transition is in flight `tick()` and `render()` are no-ops, so a
 * slow load stalls the simulation instead of running it against a half-built screen.
 */
import { Container } from 'pixi.js';

import type { AudioPlayer } from '../core/Audio';
import type { I18n } from '../core/I18n';
import type { Input } from '../core/Input';
import type { SuspendReason } from '../core/Lifecycle';
import type { ResolvedPlatform } from '../core/Platform';
import type { Storage } from '../core/Storage';
import type { Viewport } from '../core/Viewport';
import type { Session } from '../game/Session';

/**
 * Everything a state may reach for. Assembled once, in `main.ts`.
 *
 * `session` is T10's addition and the reason the rest can stay stateless: a state is
 * constructed from a class and takes no arguments, so "which level, with what score" has
 * to live somewhere both `MenuState` and `PlayState` can see. In the original that
 * somewhere is class `a` itself, which is exactly what `Session` is.
 */
export type Services = {
  viewport: Viewport;
  /** T12 — the resolved fit, controls and widescreen settings; see `core/Platform`. */
  platform: ResolvedPlatform;
  input: Input;
  audio: AudioPlayer;
  i18n: I18n;
  storage: Storage;
  session: Session;
};

export type StateContext = Services & {
  /** The active state's view is this container's only child. */
  readonly layer: Container;
  readonly machine: StateMachine;
};

export type StateCtor = new (ctx: StateContext) => GameState;

export abstract class GameState {
  /** Added to `ctx.layer` on entry and destroyed on exit. */
  readonly view = new Container();

  protected readonly ctx: StateContext;

  constructor(ctx: StateContext) {
    this.ctx = ctx;
  }

  /** For logs and debug overlays. */
  abstract readonly name: string;

  /** Build the screen. Load assets here; the machine waits for the promise. */
  async enter(): Promise<void> {}

  /** Release anything not owned by `view`, which the machine destroys for you. */
  exit(): void {}

  /** One 40 ms simulation step. `tick` is the loop's running count. */
  tick(_tick: number): void {}

  /** Once per animation frame. `alpha` is the fraction of a tick since the last one. */
  render(_alpha: number): void {}

  /**
   * T12 — the screen went away or the window lost focus; see `core/Lifecycle`. Ticks stop
   * either way, so this is only for a state that wants to *act* on the interruption, the
   * way `d.hideNotify()` does. Default: nothing.
   */
  suspend(_reason: SuspendReason): void {}

  /** The other half. Default: nothing — the tick simply resumes. */
  resume(): void {}
}

export class StateMachine {
  readonly ctx: StateContext;

  private state: GameState | null = null;

  private transition: Promise<void> | null = null;

  constructor(services: Services, layer: Container = new Container()) {
    // `viewport.screen`, not `viewport.root`: in widescreen the root is wider than 128 and
    // `screen` is the centred 128x128 every non-play screen is drawn against.
    services.viewport.screen.addChild(layer);
    this.ctx = { ...services, layer, machine: this };
  }

  get current(): GameState | null {
    return this.state;
  }

  /** True while an `enter()` is still running; the loop skips ticks meanwhile. */
  get busy(): boolean {
    return this.transition !== null;
  }

  /**
   * Swap in a new state. Returns a promise for tests and for callers that want to know
   * when the screen is up; the game loop ignores it and simply skips ticks while `busy`.
   */
  replace(Ctor: StateCtor): Promise<void> {
    const run = async (): Promise<void> => {
      // Held keys belong to the screen that was on when they went down.
      this.ctx.input.clear();

      const previous = this.state;
      this.state = null;
      if (previous) {
        previous.exit();
        this.ctx.layer.removeChild(previous.view);
        previous.view.destroy({ children: true });
      }

      const next = new Ctor(this.ctx);
      await next.enter();
      this.ctx.layer.addChild(next.view);
      this.state = next;
    };

    // Serialise transitions: two states asking to leave at once must not interleave.
    // A failed transition still releases the lock, so the game can be steered elsewhere.
    const pending = (this.transition ?? Promise.resolve()).then(run, run);
    this.transition = pending;
    const settled = pending.finally(() => {
      if (this.transition === pending) this.transition = null;
    });
    // The game loop discards this promise; a rejection here must not surface as an
    // unhandled one. Awaiting callers still see the error.
    void settled.catch(() => {});
    return settled;
  }

  tick(tick: number): void {
    if (this.transition) return;
    this.state?.tick(tick);
  }

  render(alpha: number): void {
    if (this.transition) return;
    this.state?.render(alpha);
  }

  /** Pass an interruption to the live state. A state mid-transition never sees one. */
  suspend(reason: SuspendReason): void {
    if (this.transition) return;
    this.state?.suspend(reason);
  }

  resume(): void {
    if (this.transition) return;
    this.state?.resume();
  }
}
